// Package store persists document change batches in a SQLite database.
//
// Within a document every change has a client-supplied id. New ids receive a
// monotonically increasing cursor; re-posting an existing id is idempotent
// only when the deviceId and decoded JSON payload match, otherwise it is a
// conflict. Valid batches commit atomically, so cursors never repeat and no
// record is partially written, even under concurrent writers.
//
// A document may also carry snapshots: caller-supplied JSON states pinned to
// existing change cursors. Snapshots are write-once per cursor — a matching
// re-post is idempotent, a differing one a conflict — and live apart from the
// change log.
//
// A restore appends an ordinary change whose payload is a snapshot's state.
// Restore provenance (the snapshot cursor the state came from) is persisted in
// its own table, so after restart a repeated restore is still distinguishable
// from an ordinary change and idempotency/conflict decisions are unchanged.
//
// Devices and sessions form the registration layer on top of which clients
// sync. A device registers with a client-supplied id; a session belongs to
// exactly one registered device and is addressed by its own client-supplied
// id. Registration and session creation are idempotent re-posts: the first
// call creates, an identical repeat does not. A session id already owned by
// another device is a conflict, never silently re-homed. Deletes are
// owner-scoped and hard: a repeat delete, another device, and a cross-device
// path all miss with 404, after which the id is free to be created again.
//
// Document permissions sit on top of registration: every (document, device)
// pair starts authorized, and a grant or revoke is recorded per pair. Writes
// are serialized in one transaction and committed to disk, so concurrent
// grant/revoke calls each land as a complete state and survive a restart.
// Revoking never deletes changes, snapshots or sessions; it only gates the
// session-scoped change listing.
//
// Attachments are resumable chunked uploads owned by the registered device
// that created them. Creation pins the declared total size, chunk size and
// SHA-256 digest; chunks land in any order and are stored durably as they
// arrive, so an interrupted upload resumes after a restart with its
// idempotency and conflict decisions intact. Finishing concatenates the
// chunks, verifies the digest and seals the upload; a sealed upload is
// immutable and rejects every further chunk write. Finished content is
// addressed by digest, so a second attachment with the same digest and size
// reuses the stored bytes instead of copying them.
//
// Long polling lets a caught-up client wait for subsequent changes. Waiters
// register per document before the confirming read, so a commit landing
// between that read and the park is never missed; every change-producing
// commit (batch, merge, restore, replay) signals the document's waiters after
// it commits. Wait state is in-memory only — a canceled disconnect or a
// closing store leaves no rows behind — while the changes themselves stay
// durable, so waiting and idempotency decisions are unchanged by restart.
//
// Replay is the offline retry of an ordinary batch: it shares the same
// per-document contiguous cursor space and the same serialized transaction as
// PostChanges, and additionally enforces the registration/permission layer
// (ErrDeviceNotFound, ErrPermissionDenied) before any change id is resolved,
// so its error responses never reveal change content.
package store

import (
	"context"
	"database/sql"
	"encoding/json"
	"errors"
	"fmt"
	"sync"
	"time"

	_ "modernc.org/sqlite"
)

// ErrStoreClosing reports that the store is shutting down and parked long
// polls have been woken so they can return without writing anything. The
// caller maps it to 503.
var ErrStoreClosing = errors.New("store is closing")

// ErrPermissionDenied reports that a device's access to the document has been
// revoked. The caller maps it to 403; nothing is written and no change content
// is exposed.
var ErrPermissionDenied = errors.New("device permission for this document has been revoked")

// ErrStaleCursor reports that a merge targets a base cursor for an unknown
// document, or a base cursor greater than the document's current cursor. The
// caller maps it to 400; nothing is written.
var ErrStaleCursor = errors.New("baseCursor is unknown or ahead of the current cursor")

// Change is one element of an inbound batch or one row of a listing.
type Change struct {
	ID       string          // client-supplied change id, unique per document
	DeviceID string          // originating device
	Payload  json.RawMessage // decoded JSON value, stored verbatim
}

// Result reports the outcome for one element of an accepted batch.
type Result struct {
	ID      string `json:"id"`
	Created bool   `json:"created"`
	Cursor  int64  `json:"cursor"`
}

// ListedChange is one row in a ListChanges response.
type ListedChange struct {
	ID       string          `json:"id"`
	DeviceID string          `json:"deviceId"`
	Payload  json.RawMessage `json:"payload"`
	Cursor   int64           `json:"cursor"`
}

// MergeResult reports the outcome of an accepted MergeChange. Outcome is one
// of "idempotent", "applied" or "merged".
type MergeResult struct {
	ID      string  `json:"id"`
	Outcome string  `json:"outcome"`
	Cursor  int64   `json:"cursor"`
	Result  *Result `json:"result,omitempty"`
}

// ErrConflict reports that a batch references an existing change id with a
// different deviceId or payload. The whole batch is rejected.
type ErrConflict struct {
	ID string
}

func (e *ErrConflict) Error() string {
	return fmt.Sprintf("conflicting change %q for document", e.ID)
}

// ErrSnapshotBase reports that a snapshot targets an unknown document or a
// cursor that is not an existing change cursor of the document. The caller
// maps it to 400; nothing is written.
var ErrSnapshotBase = errors.New("snapshot cursor is not an existing cursor of the document")

// ErrSnapshotNotFound reports that no snapshot exists for the document and
// cursor. The caller maps it to 404.
var ErrSnapshotNotFound = errors.New("snapshot not found")

// ErrSnapshotConflict reports that a snapshot already exists for the document
// and cursor with a different state. The stored snapshot is left unchanged.
type ErrSnapshotConflict struct {
	Cursor int64
}

func (e *ErrSnapshotConflict) Error() string {
	return fmt.Sprintf("conflicting snapshot for cursor %d", e.Cursor)
}

// ErrRestoreConflict reports that a restore references a change id that is
// already taken by an ordinary change, or by a prior restore whose deviceId,
// snapshot cursor or source state differs. Nothing is written; the caller maps
// it to 409.
type ErrRestoreConflict struct {
	ID string
}

func (e *ErrRestoreConflict) Error() string {
	return fmt.Sprintf("change id %q conflicts with the change log", e.ID)
}

// RestoreResult reports the outcome of an accepted RestoreSnapshot.
type RestoreResult struct {
	ID           string `json:"id"`
	Created      bool   `json:"created"`
	Cursor       int64  `json:"cursor"`
	RestoredFrom int64  `json:"restoredFrom"`
}

// ErrDeviceNotFound reports that an operation targets a device id that was
// never registered. The caller maps it to 404; nothing is written.
var ErrDeviceNotFound = errors.New("device not found")

// ErrSessionConflict reports that a session id already belongs to a different
// device. The session keeps its original owner; nothing is written. The
// caller maps it to 409.
type ErrSessionConflict struct {
	ID string
}

func (e *ErrSessionConflict) Error() string {
	return fmt.Sprintf("session %q belongs to another device", e.ID)
}

// ErrSessionNotFound reports that no live session matches the (device,
// session) pair: the session was never created, was already deleted, or
// belongs to another device. The caller maps it to 404.
var ErrSessionNotFound = errors.New("session not found")

// Store is the durable change log.
type Store struct {
	db *sql.DB

	// pollMu guards pollWaits, subs, crdtSubs, nextWaitID, nextSubID,
	// nextCRDTSubID and closed. Parked long polls wait on a per-document set
	// of channels; a committed change to a document closes (signals) every
	// channel parked on it. WebSocket subscriptions live in a second registry
	// keyed by (document, device): a commit signals every subscription under
	// the document, while a permission write signals only the matching
	// device's subscriptions. CRDT state subscriptions live in a third
	// registry with the same keying: a state-changing CRDT commit queues the
	// new merged state on every subscription under the document.
	pollMu        sync.Mutex
	pollWaits     map[string]map[uint64]chan struct{}
	subs          map[subKey]map[uint64]*subscription
	crdtSubs      map[crdtSubKey]map[uint64]*CRDTSubscription
	nextWaitID    uint64
	nextSubID     uint64
	nextCRDTSubID uint64
	subWG         sync.WaitGroup
	closed        bool

	// crdtMu serializes CRDT submissions against each other and against a
	// subscription's atomic register-plus-initial-read. Holding it across a
	// state-changing commit and its notification makes notifications leave in
	// transaction-commit order, and makes a commit's state land either in a
	// subscriber's initial read or in its queue, never both and never
	// neither. The single database connection already serializes the
	// transactions themselves, so this costs no concurrency.
	crdtMu sync.Mutex
}

// Open opens (creating if needed) the SQLite database at path. The empty path
// opens an in-memory database useful for tests.
func Open(path string) (*Store, error) {
	if path == "" {
		// With a single pooled connection this is a private, per-instance
		// in-memory database (useful for tests).
		path = "file::memory:"
	}
	// _txlock=immediate makes writers acquire the write lock at BEGIN, so
	// concurrent batches serialize without SQLITE_BUSY deadlocks.
	dsn := path + "?_txlock=immediate&_busy_timeout=5000&_journal_mode=WAL&_synchronous=FULL&_foreign_keys=on"
	db, err := sql.Open("sqlite", dsn)
	if err != nil {
		return nil, err
	}
	// One connection avoids cross-connection locking surprises; writes are
	// serialized by the immediate transaction anyway, and SQLite concurrency
	// for readers does not help correctness here.
	db.SetMaxOpenConns(1)
	s := &Store{
		db:        db,
		pollWaits: make(map[string]map[uint64]chan struct{}),
		subs:      make(map[subKey]map[uint64]*subscription),
		crdtSubs:  make(map[crdtSubKey]map[uint64]*CRDTSubscription),
	}
	if err := s.init(); err != nil {
		_ = db.Close()
		return nil, err
	}
	return s, nil
}

func (s *Store) init() error {
	_, err := s.db.Exec(`
CREATE TABLE IF NOT EXISTS changes (
	document_id TEXT NOT NULL,
	cursor      INTEGER NOT NULL,
	id          TEXT NOT NULL,
	device_id   TEXT NOT NULL,
	payload     BLOB NOT NULL,
	PRIMARY KEY (document_id, id)
);
CREATE UNIQUE INDEX IF NOT EXISTS changes_doc_cursor_idx
	ON changes(document_id, cursor);
CREATE TABLE IF NOT EXISTS snapshots (
	document_id TEXT NOT NULL,
	cursor      INTEGER NOT NULL,
	state       BLOB NOT NULL,
	PRIMARY KEY (document_id, cursor)
);
CREATE TABLE IF NOT EXISTS restores (
	document_id     TEXT NOT NULL,
	change_id       TEXT NOT NULL,
	device_id       TEXT NOT NULL,
	snapshot_cursor INTEGER NOT NULL,
	change_cursor   INTEGER NOT NULL,
	state           BLOB NOT NULL,
	PRIMARY KEY (document_id, change_id)
);
CREATE UNIQUE INDEX IF NOT EXISTS restores_doc_cursor_idx
	ON restores(document_id, change_cursor);
CREATE TABLE IF NOT EXISTS devices (
	id TEXT NOT NULL PRIMARY KEY
);
CREATE TABLE IF NOT EXISTS sessions (
	id        TEXT NOT NULL PRIMARY KEY,
	device_id TEXT NOT NULL REFERENCES devices(id)
);
CREATE INDEX IF NOT EXISTS sessions_device_idx
	ON sessions(device_id);
CREATE TABLE IF NOT EXISTS document_permissions (
	document_id TEXT NOT NULL,
	device_id   TEXT NOT NULL,
	authorized  INTEGER NOT NULL,
	PRIMARY KEY (document_id, device_id)
);
CREATE TABLE IF NOT EXISTS attachments (
	id          TEXT NOT NULL PRIMARY KEY,
	device_id   TEXT NOT NULL REFERENCES devices(id),
	total_bytes INTEGER NOT NULL,
	chunk_size  INTEGER NOT NULL,
	sha256      TEXT NOT NULL,
	complete    INTEGER NOT NULL DEFAULT 0,
	reused      INTEGER NOT NULL DEFAULT 0
);
CREATE TABLE IF NOT EXISTS attachment_chunks (
	attachment_id TEXT NOT NULL REFERENCES attachments(id),
	idx           INTEGER NOT NULL,
	data          BLOB NOT NULL,
	PRIMARY KEY (attachment_id, idx)
);
CREATE TABLE IF NOT EXISTS attachment_contents (
	sha256 TEXT NOT NULL PRIMARY KEY,
	size   INTEGER NOT NULL,
	data   BLOB NOT NULL
);
` + crdtSchema)
	return err
}

// InterruptWaits wakes every parked long poll without closing the database,
// so an orderly server shutdown drains waiting connections immediately
// (they answer 503) instead of holding Shutdown hostage until their wait
// deadline. Committed state is untouched.
func (s *Store) InterruptWaits() {
	s.pollMu.Lock()
	s.closed = true
	waits := s.pollWaits
	s.pollWaits = map[string]map[uint64]chan struct{}{}
	// Snapshot the live subscription channels without reaping the registry:
	// unregister remains valid while handlers drain, so the WaitGroup in
	// Close balances. New AddSubscription calls fail fast on closed.
	var subChans []chan struct{}
	for _, set := range s.subs {
		for _, sub := range set {
			subChans = append(subChans, sub.wakes)
		}
	}
	s.pollMu.Unlock()
	for _, set := range waits {
		for _, ch := range set {
			close(ch)
		}
	}
	// Live subscriptions get one last wakeup as well; the server re-checks
	// the closed flag and finishes the connection with a going-away close.
	for _, ch := range subChans {
		select {
		case ch <- struct{}{}:
		default:
		}
	}
	// CRDT state subscriptions get the same final wakeup.
	s.wakeCRDTSubscribers()
}

// Close releases the database handle. Parked long polls are woken first so
// they stop waiting and return without writing; the wake happens before the
// handle closes, so a waiter never observes a closed database. WebSocket
// subscriptions (change-log and CRDT state alike) are likewise woken and
// drained (every handler unregisters) before the handle closes.
func (s *Store) Close() error {
	s.InterruptWaits()
	s.subWG.Wait()
	return s.db.Close()
}

// registerWait parks a channel for documentID and returns it together with a
// removal function. The channel is closed on the next committed change to the
// document, or when the store closes.
func (s *Store) registerWait(documentID string) (ch chan struct{}, remove func()) {
	ch = make(chan struct{}, 1)

	s.pollMu.Lock()
	defer s.pollMu.Unlock()
	if s.closed {
		// Close beat the registration: signal immediately so the caller does
		// not park on a channel nobody will close.
		close(ch)
		return ch, func() {}
	}
	s.nextWaitID++
	id := s.nextWaitID
	set := s.pollWaits[documentID]
	if set == nil {
		set = make(map[uint64]chan struct{})
		s.pollWaits[documentID] = set
	}
	set[id] = ch
	return ch, func() {
		s.pollMu.Lock()
		if set, ok := s.pollWaits[documentID]; ok {
			delete(set, id)
			if len(set) == 0 {
				delete(s.pollWaits, documentID)
			}
		}
		s.pollMu.Unlock()
	}
}

// notifyWaiters signals every long poll parked on documentID and every
// WebSocket subscription open on it. It is called only after a
// change-bearing transaction has committed, so parked readers observe the
// new rows when they re-query and pushed frames describe committed changes.
func (s *Store) notifyWaiters(documentID string) {
	s.pollMu.Lock()
	set := s.pollWaits[documentID]
	delete(s.pollWaits, documentID)
	s.pollMu.Unlock()
	for _, ch := range set {
		close(ch)
	}
	s.signalSubscribers(documentID)
}

// WaitForChanges blocks until documentID has a change with cursor greater than
// after, a change is committed while waiting, wait elapses, ctx is canceled
// (the client disconnected) or the store closes. It then returns the current
// page of up to limit changes exactly as ListChanges would, with timedOut=true
// only when the wait deadline expired with no new rows.
//
// Registration precedes the first query: a commit landing between the read and
// the park still notifies a registered channel, so no change is missed.
//
// An unknown document is never parked on: it returns immediately with an empty
// list and nextCursor 0, timedOut=false. Data already past after is likewise
// returned immediately. wait <= 0 is an immediately expired deadline.
func (s *Store) WaitForChanges(ctx context.Context, documentID string, after, limit int64, wait time.Duration) (changes []ListedChange, nextCursor int64, timedOut bool, err error) {
	ch, remove := s.registerWait(documentID)
	defer remove()

	changes, nextCursor, err = s.ListChanges(documentID, after, limit)
	if err != nil || len(changes) > 0 {
		return changes, nextCursor, false, err
	}

	// Empty page: distinguish an unknown document (immediate empty/0, never
	// parked on) from a known document caught up to after.
	known, err := s.DocumentExists(documentID)
	if err != nil || !known {
		return changes, 0, false, err
	}

	// Known document, nothing new: a zero wait is an immediately expired
	// deadline; ListChanges already echoes nextCursor == after.
	if wait <= 0 {
		return changes, nextCursor, true, nil
	}

	timer := time.NewTimer(wait)
	defer timer.Stop()

	select {
	case <-ch:
		// Woken by a committed change or by Close.
		s.pollMu.Lock()
		closing := s.closed
		s.pollMu.Unlock()
		if closing {
			return nil, 0, false, ErrStoreClosing
		}
		changes, nextCursor, err = s.ListChanges(documentID, after, limit)
		return changes, nextCursor, len(changes) == 0, err
	case <-timer.C:
		// Timeout with no new rows: echo the caller's cursor without
		// advancing it. The document was known above, so ListChanges returns
		// nextCursor == after for an empty page.
		changes, nextCursor, err = s.ListChanges(documentID, after, limit)
		return changes, nextCursor, len(changes) == 0, err
	case <-ctx.Done():
		return nil, 0, false, ctx.Err()
	}
}

// DocumentExists reports whether documentID has any change row and is
// therefore a known document rather than an empty namespace.
func (s *Store) DocumentExists(documentID string) (bool, error) {
	var known bool
	if err := s.db.QueryRow(
		`SELECT EXISTS(SELECT 1 FROM changes WHERE document_id = ?)`,
		documentID,
	).Scan(&known); err != nil {
		return false, err
	}
	return known, nil
}

// PostChanges validates and commits one batch atomically.
//
// Every change must have a non-empty id; duplicate ids within the batch are
// rejected by the caller before reaching this point. On conflict the returned
// error is *ErrConflict and nothing is written. Cursors are assigned in batch
// order to ids that do not yet exist. Results are returned in the same order
// as the input.
func (s *Store) PostChanges(documentID string, changes []Change) ([]Result, error) {
	tx, err := s.db.Begin()
	if err != nil {
		return nil, err
	}
	defer func() { _ = tx.Rollback() }()

	results := make([]Result, len(changes))

	// First pass: resolve every id against existing rows. A single mismatch
	// aborts the whole batch before any cursor is allocated.
	pending := make([]int, 0, len(changes))
	for i, c := range changes {
		var existingDevice string
		var existingPayload []byte
		var existingCursor int64
		err := tx.QueryRow(
			`SELECT cursor, device_id, payload FROM changes WHERE document_id = ? AND id = ?`,
			documentID, c.ID,
		).Scan(&existingCursor, &existingDevice, &existingPayload)
		switch {
		case errors.Is(err, sql.ErrNoRows):
			pending = append(pending, i)
		case err != nil:
			return nil, err
		default:
			if existingDevice != c.DeviceID || !jsonEqual(existingPayload, c.Payload) {
				return nil, &ErrConflict{ID: c.ID}
			}
			results[i] = Result{
				ID:      c.ID,
				Created: false,
				Cursor:  existingCursor,
			}
		}
	}

	// Allocate cursors for genuinely new ids.
	var nextCursor int64
	if err := tx.QueryRow(
		`SELECT COALESCE(MAX(cursor), 0) + 1 FROM changes WHERE document_id = ?`,
		documentID,
	).Scan(&nextCursor); err != nil {
		return nil, err
	}
	for _, i := range pending {
		c := changes[i]
		if _, err := tx.Exec(
			`INSERT INTO changes (document_id, cursor, id, device_id, payload) VALUES (?, ?, ?, ?, ?)`,
			documentID, nextCursor, c.ID, c.DeviceID, []byte(c.Payload),
		); err != nil {
			return nil, err
		}
		results[i] = Result{
			ID:      c.ID,
			Created: true,
			Cursor:  nextCursor,
		}
		nextCursor++
	}

	if err := tx.Commit(); err != nil {
		return nil, err
	}
	if len(pending) > 0 {
		s.notifyWaiters(documentID)
	}
	return results, nil
}

// ReplayChanges commits a retried offline batch with exactly the same change
// semantics as PostChanges: ids resolve against the existing log, matching ids
// are idempotent only when deviceID and the decoded payload match, a mismatch
// is *ErrConflict and aborts the whole batch, and new ids take contiguous
// cursors in input order in one serialized transaction.
//
// Unlike PostChanges it additionally enforces the registration/permission
// layer before touching the log: an unregistered device yields
// ErrDeviceNotFound (404) and a revoked device yields ErrPermissionDenied
// (403). None of those outcomes writes anything or exposes change content.
func (s *Store) ReplayChanges(documentID string, changes []Change) ([]Result, error) {
	tx, err := s.db.Begin()
	if err != nil {
		return nil, err
	}
	defer func() { _ = tx.Rollback() }()

	// Gate first, in the same transaction: the device row and the permission
	// row are read before any change id is resolved, so a rejected replay
	// cannot observe (and its error cannot reveal) change content.
	var deviceExists bool
	if err := tx.QueryRow(
		`SELECT EXISTS(SELECT 1 FROM devices WHERE id = ?)`, changes[0].DeviceID,
	).Scan(&deviceExists); err != nil {
		return nil, err
	}
	if !deviceExists {
		return nil, ErrDeviceNotFound
	}
	var stored int
	err = tx.QueryRow(
		`SELECT authorized FROM document_permissions WHERE document_id = ? AND device_id = ?`,
		documentID, changes[0].DeviceID,
	).Scan(&stored)
	switch {
	case errors.Is(err, sql.ErrNoRows):
		// No deviation row: devices start authorized.
	case err != nil:
		return nil, err
	default:
		if stored == 0 {
			return nil, ErrPermissionDenied
		}
	}

	results := make([]Result, len(changes))

	// Resolve every id before allocating anything.
	pending := make([]int, 0, len(changes))
	for i, c := range changes {
		var existingDevice string
		var existingPayload []byte
		var existingCursor int64
		err := tx.QueryRow(
			`SELECT cursor, device_id, payload FROM changes WHERE document_id = ? AND id = ?`,
			documentID, c.ID,
		).Scan(&existingCursor, &existingDevice, &existingPayload)
		switch {
		case errors.Is(err, sql.ErrNoRows):
			pending = append(pending, i)
		case err != nil:
			return nil, err
		default:
			if existingDevice != c.DeviceID || !jsonEqual(existingPayload, c.Payload) {
				return nil, &ErrConflict{ID: c.ID}
			}
			results[i] = Result{
				ID:      c.ID,
				Created: false,
				Cursor:  existingCursor,
			}
		}
	}

	var nextCursor int64
	if err := tx.QueryRow(
		`SELECT COALESCE(MAX(cursor), 0) + 1 FROM changes WHERE document_id = ?`,
		documentID,
	).Scan(&nextCursor); err != nil {
		return nil, err
	}
	for _, i := range pending {
		c := changes[i]
		if _, err := tx.Exec(
			`INSERT INTO changes (document_id, cursor, id, device_id, payload) VALUES (?, ?, ?, ?, ?)`,
			documentID, nextCursor, c.ID, c.DeviceID, []byte(c.Payload),
		); err != nil {
			return nil, err
		}
		results[i] = Result{
			ID:      c.ID,
			Created: true,
			Cursor:  nextCursor,
		}
		nextCursor++
	}

	if err := tx.Commit(); err != nil {
		return nil, err
	}
	if len(pending) > 0 {
		s.notifyWaiters(documentID)
	}
	return results, nil
}

// MergeChange validates and appends one change against a caller-observed base
// cursor, all within a single serialized transaction.
//
//   - An existing id is idempotent only when deviceId and the decoded payload
//     match (Outcome "idempotent", with the original Result); a mismatch is an
//     *ErrConflict and nothing is written.
//   - A new id with baseCursor equal to the current cursor is appended as
//     "applied".
//   - A new id with a base cursor behind the current one is appended as
//     "merged" only when every change after baseCursor carries a JSON object
//     payload whose top-level keys are disjoint from the new payload's; any
//     non-object later payload or shared key is an *ErrConflict.
//
// A non-zero baseCursor for an unknown document, or a baseCursor greater than
// the current cursor, returns ErrStaleCursor. An unknown document with
// baseCursor 0 accepts the first change as "applied".
func (s *Store) MergeChange(documentID string, baseCursor int64, c Change) (MergeResult, error) {
	tx, err := s.db.Begin()
	if err != nil {
		return MergeResult{}, err
	}
	defer func() { _ = tx.Rollback() }()

	// Current cursor is the document's high-water mark, 0 when unknown.
	var current int64
	if err := tx.QueryRow(
		`SELECT COALESCE(MAX(cursor), 0) FROM changes WHERE document_id = ?`,
		documentID,
	).Scan(&current); err != nil {
		return MergeResult{}, err
	}
	if baseCursor > current || (baseCursor != 0 && current == 0) {
		return MergeResult{}, ErrStaleCursor
	}

	// An existing id keeps the original idempotency/conflict rules.
	var existingDevice string
	var existingPayload []byte
	var existingCursor int64
	err = tx.QueryRow(
		`SELECT cursor, device_id, payload FROM changes WHERE document_id = ? AND id = ?`,
		documentID, c.ID,
	).Scan(&existingCursor, &existingDevice, &existingPayload)
	switch {
	case errors.Is(err, sql.ErrNoRows):
		// New id; fall through to append logic below.
	case err != nil:
		return MergeResult{}, err
	default:
		if existingDevice != c.DeviceID || !jsonEqual(existingPayload, c.Payload) {
			return MergeResult{}, &ErrConflict{ID: c.ID}
		}
		return MergeResult{
			ID:      c.ID,
			Outcome: "idempotent",
			Cursor:  existingCursor,
			Result: &Result{
				ID:      c.ID,
				Created: false,
				Cursor:  existingCursor,
			},
		}, nil
	}

	outcome := "applied"
	if baseCursor < current {
		// Merge is allowed only when every change after baseCursor is a JSON
		// object whose top-level keys do not collide with the new payload's.
		newKeys, err := objectKeys(c.Payload)
		if err != nil {
			if errors.Is(err, errNotObject) {
				return MergeResult{}, &ErrConflict{ID: c.ID}
			}
			return MergeResult{}, err
		}
		rows, err := tx.Query(
			`SELECT payload FROM changes
			 WHERE document_id = ? AND cursor > ?
			 ORDER BY cursor ASC`,
			documentID, baseCursor,
		)
		if err != nil {
			return MergeResult{}, err
		}
		for rows.Next() {
			var laterPayload []byte
			if err := rows.Scan(&laterPayload); err != nil {
				_ = rows.Close()
				return MergeResult{}, err
			}
			laterKeys, err := objectKeys(laterPayload)
			if err != nil {
				_ = rows.Close()
				if errors.Is(err, errNotObject) {
					return MergeResult{}, &ErrConflict{ID: c.ID}
				}
				return MergeResult{}, err
			}
			for k := range newKeys {
				if _, clash := laterKeys[k]; clash {
					_ = rows.Close()
					return MergeResult{}, &ErrConflict{ID: c.ID}
				}
			}
		}
		if err := rows.Err(); err != nil {
			_ = rows.Close()
			return MergeResult{}, err
		}
		_ = rows.Close()
		outcome = "merged"
	}

	next := current + 1
	if _, err := tx.Exec(
		`INSERT INTO changes (document_id, cursor, id, device_id, payload) VALUES (?, ?, ?, ?, ?)`,
		documentID, next, c.ID, c.DeviceID, []byte(c.Payload),
	); err != nil {
		return MergeResult{}, err
	}

	if err := tx.Commit(); err != nil {
		return MergeResult{}, err
	}
	s.notifyWaiters(documentID)
	return MergeResult{ID: c.ID, Outcome: outcome, Cursor: next}, nil
}

// PutSnapshot stores state as the snapshot of documentID at cursor, creating
// it on first use and reporting whether this call created it.
//
// Only cursors of existing changes are valid snapshot points: an unknown
// document, a cursor below 1 or a cursor ahead of the document's current
// cursor yields ErrSnapshotBase and nothing is written. Re-posting a state
// that decodes equal to the stored one is idempotent (created=false); a
// different state is an *ErrSnapshotConflict and the stored snapshot is left
// unchanged. Snapshots are independent of the change log: they neither move
// the document's cursor nor affect merges.
func (s *Store) PutSnapshot(documentID string, cursor int64, state json.RawMessage) (bool, error) {
	tx, err := s.db.Begin()
	if err != nil {
		return false, err
	}
	defer func() { _ = tx.Rollback() }()

	var current int64
	if err := tx.QueryRow(
		`SELECT COALESCE(MAX(cursor), 0) FROM changes WHERE document_id = ?`,
		documentID,
	).Scan(&current); err != nil {
		return false, err
	}
	if current == 0 || cursor < 1 || cursor > current {
		return false, ErrSnapshotBase
	}

	var existing []byte
	err = tx.QueryRow(
		`SELECT state FROM snapshots WHERE document_id = ? AND cursor = ?`,
		documentID, cursor,
	).Scan(&existing)
	switch {
	case errors.Is(err, sql.ErrNoRows):
		if _, err := tx.Exec(
			`INSERT INTO snapshots (document_id, cursor, state) VALUES (?, ?, ?)`,
			documentID, cursor, []byte(state),
		); err != nil {
			return false, err
		}
		if err := tx.Commit(); err != nil {
			return false, err
		}
		return true, nil
	case err != nil:
		return false, err
	default:
		if !jsonEqual(existing, state) {
			return false, &ErrSnapshotConflict{Cursor: cursor}
		}
		return false, nil
	}
}

// GetSnapshot returns the state stored for documentID at cursor. Any miss —
// unknown document, unknown cursor or absent snapshot — yields
// ErrSnapshotNotFound.
func (s *Store) GetSnapshot(documentID string, cursor int64) (json.RawMessage, error) {
	var state []byte
	err := s.db.QueryRow(
		`SELECT state FROM snapshots WHERE document_id = ? AND cursor = ?`,
		documentID, cursor,
	).Scan(&state)
	switch {
	case errors.Is(err, sql.ErrNoRows):
		return nil, ErrSnapshotNotFound
	case err != nil:
		return nil, err
	default:
		return json.RawMessage(state), nil
	}
}

// RestoreSnapshot appends one ordinary change whose payload is the state of
// documentID's snapshot at snapshotCursor, all within a single serialized
// transaction.
//
//   - A snapshot miss (unknown document or a cursor without a snapshot)
//     returns ErrSnapshotNotFound; nothing is written.
//   - If changeID already belongs to a prior restore, the call is idempotent
//     only when deviceId, snapshotCursor and the decoded source state all
//     match; the first result (created=false, original cursor) is returned.
//   - If changeID is taken by an ordinary change, or a restore whose provenance
//     differs, the call returns *ErrRestoreConflict; nothing is written.
//
// Otherwise a new change is appended with the next document cursor and the
// restore provenance is recorded. Old rows are never modified.
func (s *Store) RestoreSnapshot(documentID string, deviceID, changeID string, snapshotCursor int64) (RestoreResult, error) {
	tx, err := s.db.Begin()
	if err != nil {
		return RestoreResult{}, err
	}
	defer func() { _ = tx.Rollback() }()

	// The snapshot must exist; its state is the payload to append.
	var state []byte
	err = tx.QueryRow(
		`SELECT state FROM snapshots WHERE document_id = ? AND cursor = ?`,
		documentID, snapshotCursor,
	).Scan(&state)
	switch {
	case errors.Is(err, sql.ErrNoRows):
		return RestoreResult{}, ErrSnapshotNotFound
	case err != nil:
		return RestoreResult{}, err
	}

	// Resolve the change id: an ordinary row and a prior restore are handled
	// differently, so consult both tables.
	var existingCursor int64
	var existingDevice string
	var existingPayload []byte
	err = tx.QueryRow(
		`SELECT cursor, device_id, payload FROM changes WHERE document_id = ? AND id = ?`,
		documentID, changeID,
	).Scan(&existingCursor, &existingDevice, &existingPayload)
	switch {
	case errors.Is(err, sql.ErrNoRows):
		// New id; fall through to append below.
	case err != nil:
		return RestoreResult{}, err
	default:
		var restDevice string
		var restSnapshotCursor int64
		var restState []byte
		err = tx.QueryRow(
			`SELECT device_id, snapshot_cursor, state FROM restores WHERE document_id = ? AND change_id = ?`,
			documentID, changeID,
		).Scan(&restDevice, &restSnapshotCursor, &restState)
		switch {
		case errors.Is(err, sql.ErrNoRows):
			// The id belongs to an ordinary change (or a batch/merge change),
			// not a restore: never treat it as an idempotent restore.
			return RestoreResult{}, &ErrRestoreConflict{ID: changeID}
		case err != nil:
			return RestoreResult{}, err
		default:
			if restDevice != deviceID || restSnapshotCursor != snapshotCursor || !jsonEqual(restState, state) {
				return RestoreResult{}, &ErrRestoreConflict{ID: changeID}
			}
			return RestoreResult{
				ID:           changeID,
				Created:      false,
				Cursor:       existingCursor,
				RestoredFrom: snapshotCursor,
			}, nil
		}
	}

	var nextCursor int64
	if err := tx.QueryRow(
		`SELECT COALESCE(MAX(cursor), 0) + 1 FROM changes WHERE document_id = ?`,
		documentID,
	).Scan(&nextCursor); err != nil {
		return RestoreResult{}, err
	}
	if _, err := tx.Exec(
		`INSERT INTO changes (document_id, cursor, id, device_id, payload) VALUES (?, ?, ?, ?, ?)`,
		documentID, nextCursor, changeID, deviceID, state,
	); err != nil {
		return RestoreResult{}, err
	}
	if _, err := tx.Exec(
		`INSERT INTO restores (document_id, change_id, device_id, snapshot_cursor, change_cursor, state)
		 VALUES (?, ?, ?, ?, ?, ?)`,
		documentID, changeID, deviceID, snapshotCursor, nextCursor, state,
	); err != nil {
		return RestoreResult{}, err
	}

	if err := tx.Commit(); err != nil {
		return RestoreResult{}, err
	}
	s.notifyWaiters(documentID)
	return RestoreResult{
		ID:           changeID,
		Created:      true,
		Cursor:       nextCursor,
		RestoredFrom: snapshotCursor,
	}, nil
}

// RegisterDevice registers a device by client-supplied id. The first call for
// an id creates it and reports created=true; repeating the registration is
// idempotent (created=false). Device identity never changes.
func (s *Store) RegisterDevice(deviceID string) (created bool, err error) {
	tx, err := s.db.Begin()
	if err != nil {
		return false, err
	}
	defer func() { _ = tx.Rollback() }()

	var exists bool
	if err := tx.QueryRow(
		`SELECT EXISTS(SELECT 1 FROM devices WHERE id = ?)`, deviceID,
	).Scan(&exists); err != nil {
		return false, err
	}
	if !exists {
		if _, err := tx.Exec(`INSERT INTO devices (id) VALUES (?)`, deviceID); err != nil {
			return false, err
		}
		if err := tx.Commit(); err != nil {
			return false, err
		}
		return true, nil
	}
	// An idempotent repeat commits nothing; releasing the read transaction is
	// enough.
	return false, tx.Commit()
}

// CreateSession creates a session owned by deviceID with a client-supplied id.
//
//   - An unknown device yields ErrDeviceNotFound; nothing is written.
//   - A session id already owned by another device yields *ErrSessionConflict;
//     nothing is written and the owner is unchanged.
//   - Re-posting the same (device, session) pair is idempotent: created=false.
//
// A deleted session is gone for good, so its id can be registered again as a
// brand-new session (created=true). The lookup, owner check and insert run in
// one serialized transaction, so concurrent creates of the same session id
// cannot both create it.
func (s *Store) CreateSession(deviceID, sessionID string) (created bool, err error) {
	tx, err := s.db.Begin()
	if err != nil {
		return false, err
	}
	defer func() { _ = tx.Rollback() }()

	var deviceExists bool
	if err := tx.QueryRow(
		`SELECT EXISTS(SELECT 1 FROM devices WHERE id = ?)`, deviceID,
	).Scan(&deviceExists); err != nil {
		return false, err
	}
	if !deviceExists {
		return false, ErrDeviceNotFound
	}

	var owner string
	err = tx.QueryRow(
		`SELECT device_id FROM sessions WHERE id = ?`, sessionID,
	).Scan(&owner)
	switch {
	case errors.Is(err, sql.ErrNoRows):
		if _, err := tx.Exec(
			`INSERT INTO sessions (id, device_id) VALUES (?, ?)`,
			sessionID, deviceID,
		); err != nil {
			return false, err
		}
		if err := tx.Commit(); err != nil {
			return false, err
		}
		return true, nil
	case err != nil:
		return false, err
	}

	if owner != deviceID {
		return false, &ErrSessionConflict{ID: sessionID}
	}
	return false, tx.Commit()
}

// DeleteSession removes the live session matching the (deviceID, sessionID)
// pair. Any miss — the session does not exist, was already deleted, or belongs
// to another device — returns ErrSessionNotFound and changes nothing. The
// check and the delete run in one transaction, so a concurrent create cannot
// interleave and a repeat delete still misses; the removal is committed to
// disk before the call returns.
func (s *Store) DeleteSession(deviceID, sessionID string) error {
	tx, err := s.db.Begin()
	if err != nil {
		return err
	}
	defer func() { _ = tx.Rollback() }()

	var owner string
	err = tx.QueryRow(
		`SELECT device_id FROM sessions WHERE id = ?`, sessionID,
	).Scan(&owner)
	switch {
	case errors.Is(err, sql.ErrNoRows):
		return ErrSessionNotFound
	case err != nil:
		return err
	}
	if owner != deviceID {
		return ErrSessionNotFound
	}

	if _, err := tx.Exec(
		`DELETE FROM sessions WHERE id = ? AND device_id = ?`,
		sessionID, deviceID,
	); err != nil {
		return err
	}
	return tx.Commit()
}

// SessionExists reports whether a live session with sessionID exists. Ownership
// is intentionally not part of this check: session-scoped reads only require
// that the session currently exists.
func (s *Store) SessionExists(sessionID string) (bool, error) {
	var exists bool
	if err := s.db.QueryRow(
		`SELECT EXISTS(SELECT 1 FROM sessions WHERE id = ?)`, sessionID,
	).Scan(&exists); err != nil {
		return false, err
	}
	return exists, nil
}

// SessionDevice returns the id of the device that owns the live session
// sessionID. A session that was never created or was deleted yields
// ErrSessionNotFound.
func (s *Store) SessionDevice(sessionID string) (string, error) {
	var deviceID string
	err := s.db.QueryRow(
		`SELECT device_id FROM sessions WHERE id = ?`, sessionID,
	).Scan(&deviceID)
	switch {
	case errors.Is(err, sql.ErrNoRows):
		return "", ErrSessionNotFound
	case err != nil:
		return "", err
	default:
		return deviceID, nil
	}
}

// SetDocumentPermission grants or revokes deviceID's access to documentID and
// reports whether the stored permission actually changed.
//
// Every device starts authorized for every document, so the first revoke is
// the first write for the pair (changed=true); repeating a state that already
// holds writes nothing and reports changed=false. An unregistered device
// yields ErrDeviceNotFound and nothing is written. The lookup and the write
// run in one serialized transaction, so concurrent grant/revoke calls each
// commit completely and the final state matches the last committed action.
func (s *Store) SetDocumentPermission(documentID, deviceID string, authorized bool) (changed bool, err error) {
	tx, err := s.db.Begin()
	if err != nil {
		return false, err
	}
	defer func() { _ = tx.Rollback() }()

	var deviceExists bool
	if err := tx.QueryRow(
		`SELECT EXISTS(SELECT 1 FROM devices WHERE id = ?)`, deviceID,
	).Scan(&deviceExists); err != nil {
		return false, err
	}
	if !deviceExists {
		return false, ErrDeviceNotFound
	}

	current := true // devices start authorized; a row only records a deviation
	var stored int
	err = tx.QueryRow(
		`SELECT authorized FROM document_permissions WHERE document_id = ? AND device_id = ?`,
		documentID, deviceID,
	).Scan(&stored)
	switch {
	case errors.Is(err, sql.ErrNoRows):
		// No row: the default (authorized) holds.
	case err != nil:
		return false, err
	default:
		current = stored != 0
	}
	if current == authorized {
		return false, tx.Commit()
	}

	v := 0
	if authorized {
		v = 1
	}
	if _, err := tx.Exec(
		`INSERT INTO document_permissions (document_id, device_id, authorized) VALUES (?, ?, ?)
		 ON CONFLICT (document_id, device_id) DO UPDATE SET authorized = excluded.authorized`,
		documentID, deviceID, v,
	); err != nil {
		return false, err
	}
	if err := tx.Commit(); err != nil {
		return false, err
	}
	// A grant cannot unblock a subscription (the first revoke already ended
	// it, stickily); only a revoke needs to end live subscriptions.
	if !authorized {
		s.signalRevokedSubscribers(documentID, deviceID)
		s.signalRevokedCRDTSubscribers(documentID, deviceID)
	}
	return true, nil
}

// DocumentAuthorized reports whether deviceID currently holds permission for
// documentID. Devices start authorized, so an absent row means authorized.
func (s *Store) DocumentAuthorized(documentID, deviceID string) (bool, error) {
	var stored int
	err := s.db.QueryRow(
		`SELECT authorized FROM document_permissions WHERE document_id = ? AND device_id = ?`,
		documentID, deviceID,
	).Scan(&stored)
	switch {
	case errors.Is(err, sql.ErrNoRows):
		return true, nil
	case err != nil:
		return false, err
	default:
		return stored != 0, nil
	}
}

// errNotObject marks a payload that is not a JSON object.
var errNotObject = errors.New("payload is not a JSON object")

// objectKeys returns the top-level keys of a JSON object payload. A null,
// array or scalar payload yields errNotObject.
func objectKeys(raw json.RawMessage) (map[string]struct{}, error) {
	var m map[string]json.RawMessage
	if err := json.Unmarshal(raw, &m); err != nil {
		// Valid JSON that is not an object (array, scalar, null) decodes with
		// a type error into a map; treat it and malformed JSON as non-object.
		return nil, errNotObject
	}
	if m == nil {
		return nil, errNotObject
	}
	keys := make(map[string]struct{}, len(m))
	for k := range m {
		keys[k] = struct{}{}
	}
	return keys, nil
}

// ListChanges returns at most limit changes for documentID whose cursor is
// greater than after, in cursor order, together with the cursor to pass as
// the next after value. An unknown document yields an empty list and cursor 0;
// a known document with no rows past after yields nextCursor == after.
func (s *Store) ListChanges(documentID string, after, limit int64) ([]ListedChange, int64, error) {
	rows, err := s.db.Query(
		`SELECT id, device_id, payload, cursor FROM changes
		 WHERE document_id = ? AND cursor > ?
		 ORDER BY cursor ASC
		 LIMIT ?`,
		documentID, after, limit,
	)
	if err != nil {
		return nil, 0, err
	}
	defer func() { _ = rows.Close() }()

	out := make([]ListedChange, 0)
	var maxCursor int64 = after
	for rows.Next() {
		var c ListedChange
		if err := rows.Scan(&c.ID, &c.DeviceID, &c.Payload, &c.Cursor); err != nil {
			return nil, 0, err
		}
		out = append(out, c)
		maxCursor = c.Cursor
	}
	if err := rows.Err(); err != nil {
		return nil, 0, err
	}

	// Distinguish an unknown document from a known one with nothing new:
	// unknown documents must report nextCursor 0.
	if len(out) == 0 {
		var known bool
		if err := s.db.QueryRow(
			`SELECT EXISTS(SELECT 1 FROM changes WHERE document_id = ?)`,
			documentID,
		).Scan(&known); err != nil {
			return nil, 0, err
		}
		if !known {
			return out, 0, nil
		}
	}
	return out, maxCursor, nil
}

// jsonEqual reports whether two payloads are equal after JSON decoding, so
// 1 and 1.0, or {"a":1,"b":2} and {"b":2,"a":1}, compare equal.
func jsonEqual(a, b json.RawMessage) bool {
	var va, vb any
	if err := json.Unmarshal(a, &va); err != nil {
		return false
	}
	if err := json.Unmarshal(b, &vb); err != nil {
		return false
	}
	return deepEqual(va, vb)
}

func deepEqual(a, b any) bool {
	switch av := a.(type) {
	case nil:
		return b == nil
	case bool:
		bv, ok := b.(bool)
		return ok && av == bv
	case string:
		bv, ok := b.(string)
		return ok && av == bv
	case float64:
		bv, ok := b.(float64)
		return ok && av == bv
	case []any:
		bv, ok := b.([]any)
		if !ok || len(av) != len(bv) {
			return false
		}
		for i := range av {
			if !deepEqual(av[i], bv[i]) {
				return false
			}
		}
		return true
	case map[string]any:
		bv, ok := b.(map[string]any)
		if !ok || len(av) != len(bv) {
			return false
		}
		for k, v := range av {
			w, exists := bv[k]
			if !exists || !deepEqual(v, w) {
				return false
			}
		}
		return true
	default:
		return false
	}
}

// CRDT state sits beside the change log as an independent, automatically
// mergeable state layer. A document's CRDT type is declared with its first
// operation batch — "counter", "gset" (a grow-only set) or "register" (a
// last-writer-wins register) — and never changes afterward; two batches
// declaring different types concurrently serialize in one transaction and
// exactly one takes effect.
//
// A counter operation carries the originating device's accumulated
// contribution. Each device's contribution only moves forward (a regressing
// value is an ErrCRDTConflict and changes nothing), and the merged state is the
// sum of every device's maximum contribution — a PN-free grow-only counter
// (GCounter), so the merge is commutative, associative and idempotent.
//
// A gset operation adds elements; the merged state is the union of every
// accepted element, presented in ascending order. Re-adding an element does
// not change the state.
//
// A register operation carries an arbitrary JSON value (null, number, string,
// array or object, stored verbatim) and a non-negative integer version. A
// device's versions only move strictly forward (a regressing or equal version
// is an ErrCRDTConflict and changes nothing), and the merged state is the
// value of the operation with the greatest version, ties broken by the
// lexicographically smaller operation id — a last-writer-wins register whose
// merge is commutative, associative and idempotent, so every reader converges
// to the same value regardless of arrival order.
//
// An orset (observed-remove set) operation either adds one element or removes
// one. Every add introduces a fresh tag (its own operation id) for the
// element; a remove tombstones exactly the tags it observes — the adds
// accepted before it — and leaves later adds untouched, so a remove concurrent
// with an add never deletes it. Removing an element that was never added (or
// is already fully removed) is an accepted no-op. The merged state is the set
// of elements with at least one live tag, presented in ascending order; the
// merge is commutative, associative and idempotent, so every reader converges
// to the same set regardless of arrival order.
//
// Every operation carries a stable, client-supplied id, unique per document.
// Re-posting the same id with the same content and origin is idempotent; the
// same id with different content or a different device is an
// ErrCRDTConflict and leaves the state untouched. Operations and the merged
// result commit together in one serialized transaction and are durable: the
// decisions and the merged state are unchanged after a restart.
//
// The CRDT layer shares the registration/permission layer with the rest of the
// service: an unregistered device yields ErrDeviceNotFound (404) and a revoked
// device yields ErrPermissionDenied (403), before any CRDT content is observed.
// It never touches the change log, document cursors, snapshots or the
// subscription machinery.

package store

import (
	"database/sql"
	"encoding/json"
	"errors"
	"fmt"
)

// CRDT document types.
const (
	// CRDTTypeCounter is the grow-only counter: the merged value is the sum of
	// each device's maximum accumulated contribution.
	CRDTTypeCounter = "counter"
	// CRDTTypeGSet is the grow-only set: the merged value is the union of all
	// added elements.
	CRDTTypeGSet = "gset"
	// CRDTTypeRegister is the last-writer-wins register: the merged value is
	// the value of the operation with the greatest version, ties broken by the
	// lexicographically smaller operation id.
	CRDTTypeRegister = "register"
	// CRDTTypeORSet is the observed-remove set: the merged value is the set of
	// elements with at least one add not tombstoned by an observed remove.
	CRDTTypeORSet = "orset"
)

// OR-Set operation actions.
const (
	// CRDTORSetAdd adds the operation's element with a fresh tag.
	CRDTORSetAdd = "add"
	// CRDTORSetRemove tombstones every add tag for the element that the
	// operation observes.
	CRDTORSetRemove = "remove"
)

// ErrCRDTNotFound reports that no CRDT operation has ever been committed for
// the document, so it has neither a type nor a merged state yet. The caller
// maps it to 404.
var ErrCRDTNotFound = errors.New("crdt state not found")

// ErrCRDTConflict reports a rejected CRDT batch: the document's type is
// already fixed to another type, a counter contribution regressed, or an
// operation id already exists with different content or origin. Nothing is
// written; the caller maps it to 409.
type ErrCRDTConflict struct {
	// ID is the conflicting operation id when one is known; it is empty for a
	// document-level conflict (a mismatched declared type).
	ID string
	// Reason carries a short, machine-facing description of the conflict.
	Reason string
}

func (e *ErrCRDTConflict) Error() string {
	if e.ID != "" {
		return fmt.Sprintf("crdt conflict for operation %q: %s", e.ID, e.Reason)
	}
	return "crdt conflict: " + e.Reason
}

// CRDTOp is one element of an inbound CRDT batch.
//
// For a counter, Value is the device's accumulated contribution: it must be a
// JSON number that is a non-negative integer, and it may never decrease for
// the same device. Elements and Version are unused.
//
// For a gset, Elements lists the strings the operation adds to the set and
// must be non-empty; Value and Version are unused.
//
// For a register, Value is an arbitrary JSON value stored verbatim and
// Version is a non-negative integer that must be strictly greater than every
// version the same device has already had accepted. Elements is unused.
//
// For an orset, Action is "add" or "remove" and Element is the non-empty
// string the operation adds or removes. Value, Elements and Version are
// unused.
type CRDTOp struct {
	ID       string          // client-supplied stable id, unique per document
	DeviceID string          // originating device (shared by the whole batch)
	Value    json.RawMessage // counter: accumulated contribution; register: the value
	Elements []string        // gset: elements to add
	Version  int64           // register: logical version, per-device strictly increasing
	Action   string          // orset: CRDTORSetAdd or CRDTORSetRemove
	Element  string          // orset: the element the action applies to
}

// CRDTState is a document's merged CRDT state.
//
// Value holds the type-specific merged result: for a counter it decodes to the
// JSON integer sum of per-device maxima; for a gset it decodes to the sorted
// JSON array of every accepted element (an empty set is []); for a register it
// is the winning operation's JSON value, exactly as submitted; for an orset it
// decodes to the sorted JSON array of the elements with at least one live add
// (an empty set is []).
type CRDTState struct {
	Type  string          `json:"type"`
	Value json.RawMessage `json:"value"`
}

// CRDTResult reports the outcome for one element of an accepted CRDT batch.
type CRDTResult struct {
	ID      string `json:"id"`
	Created bool   `json:"created"`
}

// crdtSchema is appended to the schema created in init.
const crdtSchema = `
CREATE TABLE IF NOT EXISTS crdt_documents (
	document_id TEXT NOT NULL PRIMARY KEY,
	type        TEXT NOT NULL
);
CREATE TABLE IF NOT EXISTS crdt_ops (
	document_id TEXT NOT NULL,
	id          TEXT NOT NULL,
	device_id   TEXT NOT NULL,
	value       BLOB,
	PRIMARY KEY (document_id, id)
);
CREATE TABLE IF NOT EXISTS crdt_counter_values (
	document_id TEXT NOT NULL,
	device_id   TEXT NOT NULL,
	value       INTEGER NOT NULL,
	PRIMARY KEY (document_id, device_id)
);
CREATE TABLE IF NOT EXISTS crdt_set_elements (
	document_id TEXT NOT NULL,
	element     TEXT NOT NULL,
	PRIMARY KEY (document_id, element)
);
CREATE TABLE IF NOT EXISTS crdt_register_ops (
	document_id TEXT NOT NULL,
	id          TEXT NOT NULL,
	device_id   TEXT NOT NULL,
	version     INTEGER NOT NULL,
	value       BLOB NOT NULL,
	PRIMARY KEY (document_id, id)
);
CREATE TABLE IF NOT EXISTS crdt_orset_tags (
	document_id TEXT NOT NULL,
	element     TEXT NOT NULL,
	op_id       TEXT NOT NULL,
	PRIMARY KEY (document_id, element, op_id)
);
CREATE TABLE IF NOT EXISTS crdt_orset_tombstones (
	document_id TEXT NOT NULL,
	element     TEXT NOT NULL,
	op_id       TEXT NOT NULL,
	removed_by  TEXT NOT NULL,
	PRIMARY KEY (document_id, element, op_id)
);
-- crdt_op_identities keeps, for each operation id whose merge row compaction
-- trimmed away, the only information idempotency and conflict decisions still
-- need: the originating device and a digest of the type-specific comparison
-- content. Compaction never trims this table; it does not participate in any
-- merge and holds a fixed-size digest rather than the operation payload, so
-- retaining one small row per trimmed id cannot grow the state back toward its
-- pre-compaction size.
CREATE TABLE IF NOT EXISTS crdt_op_identities (
	document_id TEXT NOT NULL,
	id          TEXT NOT NULL,
	device_id   TEXT NOT NULL,
	digest      BLOB NOT NULL,
	PRIMARY KEY (document_id, id)
);
`

// SubmitCRDTOps validates and commits one CRDT batch atomically.
//
// declaredType is the type the client asserts for the document
// ("counter", "gset", "register" or "orset"). It fixes the type on the document's
// first batch; every later batch must declare the same type. Two batches
// declaring different types race in one serialized transaction, so exactly
// one wins and the other gets an *ErrCRDTConflict (409).
//
// The device is gated first (ErrDeviceNotFound / ErrPermissionDenied) before
// any CRDT content is read. Every operation is then resolved against the
// committed history: a repeated id is idempotent only with the same device and
// content, otherwise it is an *ErrCRDTConflict; a counter contribution below
// the device's current maximum, or a register version not strictly greater
// than the device's accepted versions, is likewise an *ErrCRDTConflict. Any
// failure rejects the whole batch. Results come back in request order.
//
// When the committed batch actually moved the merged state (a counter maximum
// advanced, the set union grew, the register's winning value changed or the
// orset's live element set changed) the document's CRDT state subscribers are
// notified with the new merged state after the commit; idempotent repeats,
// rejected batches and no-op additions or removals change nothing and notify
// nobody.
func (s *Store) SubmitCRDTOps(documentID, declaredType string, ops []CRDTOp) ([]CRDTResult, error) {
	// Serialize submissions with each other and with a subscriber's atomic
	// register+initial-read: notifications then leave in commit order, and a
	// committed state lands either in the initial read or in the queue.
	s.crdtMu.Lock()
	defer s.crdtMu.Unlock()

	tx, err := s.db.Begin()
	if err != nil {
		return nil, err
	}
	defer func() { _ = tx.Rollback() }()

	deviceID := ops[0].DeviceID

	// Registration and permission are enforced before any CRDT content is
	// observed, so a rejected submission cannot reveal type or state.
	var deviceExists bool
	if err := tx.QueryRow(
		`SELECT EXISTS(SELECT 1 FROM devices WHERE id = ?)`, deviceID,
	).Scan(&deviceExists); err != nil {
		return nil, err
	}
	if !deviceExists {
		return nil, ErrDeviceNotFound
	}
	var storedAuth int
	err = tx.QueryRow(
		`SELECT authorized FROM document_permissions WHERE document_id = ? AND device_id = ?`,
		documentID, deviceID,
	).Scan(&storedAuth)
	switch {
	case errors.Is(err, sql.ErrNoRows):
		// No deviation row: devices start authorized.
	case err != nil:
		return nil, err
	default:
		if storedAuth == 0 {
			return nil, ErrPermissionDenied
		}
	}

	// Resolve the document type: fixed on the first accepted batch.
	var docType string
	err = tx.QueryRow(
		`SELECT type FROM crdt_documents WHERE document_id = ?`, documentID,
	).Scan(&docType)
	switch {
	case errors.Is(err, sql.ErrNoRows):
		// First batch for this document: its declared type wins the race.
		if _, err := tx.Exec(
			`INSERT INTO crdt_documents (document_id, type) VALUES (?, ?)`,
			documentID, declaredType,
		); err != nil {
			return nil, err
		}
		docType = declaredType
	case err != nil:
		return nil, err
	default:
		if docType != declaredType {
			return nil, &ErrCRDTConflict{
				Reason: fmt.Sprintf("document type is already %q", docType),
			}
		}
	}

	results := make([]CRDTResult, len(ops))

	var stateChanged bool
	switch docType {
	case CRDTTypeCounter:
		changed, err := applyCounterOps(tx, documentID, ops, results)
		if err != nil {
			return nil, err
		}
		stateChanged = changed
	case CRDTTypeGSet:
		changed, err := applyGSetOps(tx, documentID, ops, results)
		if err != nil {
			return nil, err
		}
		stateChanged = changed
	case CRDTTypeRegister:
		changed, err := applyRegisterOps(tx, documentID, ops, results)
		if err != nil {
			return nil, err
		}
		stateChanged = changed
	case CRDTTypeORSet:
		changed, err := applyORSetOps(tx, documentID, ops, results)
		if err != nil {
			return nil, err
		}
		stateChanged = changed
	}

	if err := tx.Commit(); err != nil {
		return nil, err
	}
	if stateChanged {
		// The committed batch moved the merged state; re-derive it (the merge
		// is never cached) and publish it after commit, so a subscriber only
		// ever observes a durable state and commits arrive in commit order.
		state, err := s.GetCRDTState(documentID)
		if err != nil {
			return results, nil
		}
		s.notifyCRDTSubscribers(documentID, state)
	}
	return results, nil
}

// applyCounterOps resolves and applies every counter operation inside tx. A
// repeated id is idempotent only with the same device and contribution. A new
// id with a contribution below the device's stored maximum regresses the
// counter and is rejected; an equal contribution is an accepted no-op; a
// larger one advances the device's maximum. It reports whether the merged
// state actually changed — only an advancing contribution moves the sum.
func applyCounterOps(tx *sql.Tx, documentID string, ops []CRDTOp, results []CRDTResult) (bool, error) {
	changed := false
	for i, op := range ops {
		value, err := decodeCounterValue(op.Value)
		if err != nil {
			return false, &ErrCRDTConflict{ID: op.ID, Reason: err.Error()}
		}

		var existingDevice string
		var existingValue []byte
		err = tx.QueryRow(
			`SELECT device_id, value FROM crdt_ops WHERE document_id = ? AND id = ?`,
			documentID, op.ID,
		).Scan(&existingDevice, &existingValue)
		switch {
		case errors.Is(err, sql.ErrNoRows):
			// The merge row may have been trimmed by compaction; the retained
			// identity still decides between idempotent replay and conflict.
			idempotent, idErr := resolveTrimmedIdentity(
				tx, documentID, CRDTTypeCounter,
				"operation id already exists with a different device or value", op,
			)
			if idErr != nil {
				return false, idErr
			}
			if idempotent {
				results[i] = CRDTResult{ID: op.ID, Created: false}
				continue
			}
			// New id: enforce monotonicity against this device's maximum.
			var current sql.NullInt64
			if scanErr := tx.QueryRow(
				`SELECT value FROM crdt_counter_values WHERE document_id = ? AND device_id = ?`,
				documentID, op.DeviceID,
			).Scan(&current); scanErr != nil && !errors.Is(scanErr, sql.ErrNoRows) {
				return false, scanErr
			}
			if current.Valid && value < current.Int64 {
				return false, &ErrCRDTConflict{
					ID:     op.ID,
					Reason: "counter contribution must not decrease",
				}
			}
			if _, err := tx.Exec(
				`INSERT INTO crdt_ops (document_id, id, device_id, value) VALUES (?, ?, ?, ?)`,
				documentID, op.ID, op.DeviceID, []byte(op.Value),
			); err != nil {
				return false, err
			}
			if !current.Valid || value > current.Int64 {
				if _, err := tx.Exec(
					`INSERT INTO crdt_counter_values (document_id, device_id, value) VALUES (?, ?, ?)
					 ON CONFLICT (document_id, device_id) DO UPDATE SET value = excluded.value`,
					documentID, op.DeviceID, value,
				); err != nil {
					return false, err
				}
				changed = true
			}
			results[i] = CRDTResult{ID: op.ID, Created: true}
		case err != nil:
			return false, err
		default:
			if existingDevice != op.DeviceID || !jsonEqual(existingValue, op.Value) {
				return false, &ErrCRDTConflict{
					ID:     op.ID,
					Reason: "operation id already exists with a different device or value",
				}
			}
			results[i] = CRDTResult{ID: op.ID, Created: false}
		}
	}
	return changed, nil
}

// applyGSetOps resolves and applies every grow-only-set operation inside tx.
// A repeated id is idempotent only with the same device and the same set of
// elements (element order is irrelevant to the merge). New elements are
// inserted into the union table; re-adding an element changes nothing. It
// reports whether the merged state actually changed — only an element that
// was not already in the union moves it.
func applyGSetOps(tx *sql.Tx, documentID string, ops []CRDTOp, results []CRDTResult) (bool, error) {
	changed := false
	for i, op := range ops {
		var existingDevice string
		var existingElements []byte
		err := tx.QueryRow(
			`SELECT device_id, value FROM crdt_ops WHERE document_id = ? AND id = ?`,
			documentID, op.ID,
		).Scan(&existingDevice, &existingElements)
		switch {
		case errors.Is(err, sql.ErrNoRows):
			// The operation row covering the union may have been trimmed; the
			// retained identity still decides replay versus conflict.
			idempotent, idErr := resolveTrimmedIdentity(
				tx, documentID, CRDTTypeGSet,
				"operation id already exists with a different device or elements", op,
			)
			if idErr != nil {
				return false, idErr
			}
			if idempotent {
				results[i] = CRDTResult{ID: op.ID, Created: false}
				continue
			}
			// New id; insert the op and its elements below.
		case err != nil:
			return false, err
		default:
			if existingDevice != op.DeviceID || !stringSetEqual(existingElements, op.Elements) {
				return false, &ErrCRDTConflict{
					ID:     op.ID,
					Reason: "operation id already exists with a different device or elements",
				}
			}
			results[i] = CRDTResult{ID: op.ID, Created: false}
			continue
		}

		if _, err := tx.Exec(
			`INSERT INTO crdt_ops (document_id, id, device_id, value) VALUES (?, ?, ?, ?)`,
			documentID, op.ID, op.DeviceID, []byte(encodeSetElements(op.Elements)),
		); err != nil {
			return false, err
		}
		for _, element := range op.Elements {
			// The union table is an identity insert: a repeated element simply
			// exists once, and only a genuinely new element moves the merge.
			res, err := tx.Exec(
				`INSERT OR IGNORE INTO crdt_set_elements (document_id, element) VALUES (?, ?)`,
				documentID, element,
			)
			if err != nil {
				return false, err
			}
			if n, err := res.RowsAffected(); err == nil && n > 0 {
				changed = true
			}
		}
		results[i] = CRDTResult{ID: op.ID, Created: true}
	}
	return changed, nil
}

// applyRegisterOps resolves and applies every register operation inside tx. A
// repeated id is idempotent only with the same device, version and value. A
// new id whose version is not strictly greater than every version already
// accepted from the same device regresses (or stalls) the device's clock and
// is rejected. It reports whether the merged state actually changed — only a
// change of the winning operation's value moves it.
func applyRegisterOps(tx *sql.Tx, documentID string, ops []CRDTOp, results []CRDTResult) (bool, error) {
	// The merged value before the batch, so a batch that leaves the winner's
	// value untouched (an idempotent replay, or a new op that loses the
	// last-writer-wins comparison) reports no change and notifies nobody.
	prev, prevOK, err := registerWinner(tx, documentID)
	if err != nil {
		return false, err
	}

	for i, op := range ops {
		if op.Version < 0 {
			// The API boundary rejects negative versions; a negative version
			// here means the caller skipped validation.
			return false, &ErrCRDTConflict{ID: op.ID, Reason: "register version must be a non-negative integer"}
		}

		var existingDevice string
		var existingVersion int64
		var existingValue []byte
		err := tx.QueryRow(
			`SELECT device_id, version, value FROM crdt_register_ops WHERE document_id = ? AND id = ?`,
			documentID, op.ID,
		).Scan(&existingDevice, &existingVersion, &existingValue)
		switch {
		case errors.Is(err, sql.ErrNoRows):
			// An older per-device version may have been trimmed; the retained
			// identity still decides replay versus conflict before the version
			// monotonicity gate, which only applies to an id never accepted.
			idempotent, idErr := resolveTrimmedIdentity(
				tx, documentID, CRDTTypeRegister,
				"operation id already exists with a different device, version or value", op,
			)
			if idErr != nil {
				return false, idErr
			}
			if idempotent {
				results[i] = CRDTResult{ID: op.ID, Created: false}
				continue
			}
			// New id: the device's versions only move strictly forward. The
			// per-device maximum is derived from the retained operations, so
			// the decision survives compaction (which keeps each device's
			// latest) and restarts without extra state.
			var maxVersion sql.NullInt64
			if scanErr := tx.QueryRow(
				`SELECT MAX(version) FROM crdt_register_ops WHERE document_id = ? AND device_id = ?`,
				documentID, op.DeviceID,
			).Scan(&maxVersion); scanErr != nil {
				return false, scanErr
			}
			if maxVersion.Valid && op.Version <= maxVersion.Int64 {
				return false, &ErrCRDTConflict{
					ID:     op.ID,
					Reason: "register version must be greater than the device's previously accepted version",
				}
			}
			if _, err := tx.Exec(
				`INSERT INTO crdt_register_ops (document_id, id, device_id, version, value) VALUES (?, ?, ?, ?, ?)`,
				documentID, op.ID, op.DeviceID, op.Version, []byte(op.Value),
			); err != nil {
				return false, err
			}
			results[i] = CRDTResult{ID: op.ID, Created: true}
		case err != nil:
			return false, err
		default:
			if existingDevice != op.DeviceID || existingVersion != op.Version || !jsonEqual(existingValue, op.Value) {
				return false, &ErrCRDTConflict{
					ID:     op.ID,
					Reason: "operation id already exists with a different device, version or value",
				}
			}
			results[i] = CRDTResult{ID: op.ID, Created: false}
		}
	}

	next, nextOK, err := registerWinner(tx, documentID)
	if err != nil {
		return false, err
	}
	// The merge is the winner's value; a new winner carrying a JSON-equal
	// value does not move the state.
	changed := prevOK != nextOK || (prevOK && nextOK && !jsonEqual(prev, next))
	return changed, nil
}

// registerWinner returns the value the register currently merges to: the
// value of the accepted operation with the greatest version, ties broken by
// the lexicographically smaller operation id. It reports false when the
// document has no accepted register operation yet.
func registerWinner(tx *sql.Tx, documentID string) (json.RawMessage, bool, error) {
	var value []byte
	err := tx.QueryRow(
		`SELECT value FROM crdt_register_ops WHERE document_id = ?
		 ORDER BY version DESC, id ASC LIMIT 1`,
		documentID,
	).Scan(&value)
	switch {
	case errors.Is(err, sql.ErrNoRows):
		return nil, false, nil
	case err != nil:
		return nil, false, err
	default:
		return json.RawMessage(value), true, nil
	}
}

// applyORSetOps resolves and applies every observed-remove-set operation
// inside tx. A repeated id is idempotent only with the same device, action and
// element; an idempotent replay applies nothing, so a replayed remove never
// tombstones adds that landed after its first acceptance. An add tags the
// element with its own operation id; a remove tombstones exactly the tags
// already accepted for the element — adds that arrive later carry fresh tags
// and are unaffected, and removing an element with no live (or no) tags is an
// accepted no-op. It reports whether the merged state actually changed — only
// a change in the set of elements with at least one live tag moves it.
func applyORSetOps(tx *sql.Tx, documentID string, ops []CRDTOp, results []CRDTResult) (bool, error) {
	// The merged element set before the batch, so a batch that leaves it
	// untouched (an idempotent replay, an add of an already-present element,
	// a remove with nothing observed) reports no change and notifies nobody.
	prev, err := queryORSetElements(tx, documentID)
	if err != nil {
		return false, err
	}

	for i, op := range ops {
		if op.Action != CRDTORSetAdd && op.Action != CRDTORSetRemove {
			// The API boundary rejects unknown actions; one here means the
			// caller skipped validation.
			return false, &ErrCRDTConflict{ID: op.ID, Reason: `orset action must be "add" or "remove"`}
		}

		var existingDevice string
		var existingContent []byte
		err := tx.QueryRow(
			`SELECT device_id, value FROM crdt_ops WHERE document_id = ? AND id = ?`,
			documentID, op.ID,
		).Scan(&existingDevice, &existingContent)
		switch {
		case errors.Is(err, sql.ErrNoRows):
			// New id; insert the op and apply its effect below.
		case err != nil:
			return false, err
		default:
			if existingDevice != op.DeviceID || !jsonEqual(existingContent, encodeORSetContent(op.Action, op.Element)) {
				return false, &ErrCRDTConflict{
					ID:     op.ID,
					Reason: "operation id already exists with a different device, action or element",
				}
			}
			results[i] = CRDTResult{ID: op.ID, Created: false}
			continue
		}

		if _, err := tx.Exec(
			`INSERT INTO crdt_ops (document_id, id, device_id, value) VALUES (?, ?, ?, ?)`,
			documentID, op.ID, op.DeviceID, []byte(encodeORSetContent(op.Action, op.Element)),
		); err != nil {
			return false, err
		}
		if op.Action == CRDTORSetAdd {
			// The tag is the operation id itself: unique per document, so the
			// insert always lands and concurrent adds of the same element
			// accumulate independent tags.
			if _, err := tx.Exec(
				`INSERT OR IGNORE INTO crdt_orset_tags (document_id, element, op_id) VALUES (?, ?, ?)`,
				documentID, op.Element, op.ID,
			); err != nil {
				return false, err
			}
		} else {
			// Tombstone exactly the tags this remove observes: the adds
			// accepted before it. Tags created later are not in the table yet
			// and survive; already-tombstoned tags are an identity insert.
			if _, err := tx.Exec(
				`INSERT OR IGNORE INTO crdt_orset_tombstones (document_id, element, op_id, removed_by)
				 SELECT ?, ?, op_id, ? FROM crdt_orset_tags
				 WHERE document_id = ? AND element = ?`,
				documentID, op.Element, op.ID, documentID, op.Element,
			); err != nil {
				return false, err
			}
		}
		results[i] = CRDTResult{ID: op.ID, Created: true}
	}

	next, err := queryORSetElements(tx, documentID)
	if err != nil {
		return false, err
	}
	return !stringSliceEqual(prev, next), nil
}

// orsetLiveElementsSQL selects the elements with at least one add tag no
// tombstone covers, in ascending order — the orset merge, derived from the
// accepted operations rather than cached.
const orsetLiveElementsSQL = `
SELECT DISTINCT element FROM crdt_orset_tags t
WHERE t.document_id = ? AND NOT EXISTS (
	SELECT 1 FROM crdt_orset_tombstones x
	WHERE x.document_id = t.document_id
	  AND x.element = t.element
	  AND x.op_id = t.op_id
)
ORDER BY element ASC`

// orsetQuerier is satisfied by both *sql.Tx (inside a submission) and *sql.DB
// (a state read), so the merge query exists exactly once.
type orsetQuerier interface {
	Query(query string, args ...any) (*sql.Rows, error)
}

// queryORSetElements returns the document's live orset elements in ascending
// order. The empty set is an empty slice, never nil, so it marshals as [].
func queryORSetElements(q orsetQuerier, documentID string) ([]string, error) {
	rows, err := q.Query(orsetLiveElementsSQL, documentID)
	if err != nil {
		return nil, err
	}
	elements := make([]string, 0)
	for rows.Next() {
		var element string
		if err := rows.Scan(&element); err != nil {
			_ = rows.Close()
			return nil, err
		}
		elements = append(elements, element)
	}
	if err := rows.Err(); err != nil {
		_ = rows.Close()
		return nil, err
	}
	_ = rows.Close()
	return elements, nil
}

// encodeORSetContent renders an orset operation's content (its action and
// element) as a JSON object for durable storage, so a later submission of the
// same id can be compared against the original content.
func encodeORSetContent(action, element string) json.RawMessage {
	raw, err := json.Marshal(struct {
		Action  string `json:"action"`
		Element string `json:"element"`
	}{Action: action, Element: element})
	if err != nil {
		// Strings always marshal.
		return json.RawMessage(`{"action":"","element":""}`)
	}
	return raw
}

// stringSliceEqual reports whether a and b hold the same strings in the same
// order. Both orset element lists are ascending, so order-sensitive equality
// is set equality.
func stringSliceEqual(a, b []string) bool {
	if len(a) != len(b) {
		return false
	}
	for i := range a {
		if a[i] != b[i] {
			return false
		}
	}
	return true
}

// decodeCounterValue requires raw to be a non-negative JSON integer with no
// fraction or exponent. Floats, strings, booleans and null are rejected at the
// API boundary; a malformed integer here means the caller skipped validation.
func decodeCounterValue(raw json.RawMessage) (int64, error) {
	var n int64
	if err := json.Unmarshal(raw, &n); err != nil || n < 0 {
		return 0, errors.New("counter value must be a non-negative integer")
	}
	return n, nil
}

// encodeSetElements renders the elements of one gset operation as a JSON array
// for durable storage of the original operation content.
func encodeSetElements(elements []string) json.RawMessage {
	raw, err := json.Marshal(elements)
	if err != nil {
		// Strings always marshal.
		return json.RawMessage("[]")
	}
	return raw
}

// stringSetEqual reports whether raw (a JSON array of strings stored for a
// prior gset operation) contains exactly the elements of want, ignoring
// duplicates and order: the content of a set operation is the set of elements.
func stringSetEqual(raw json.RawMessage, want []string) bool {
	var got []string
	if err := json.Unmarshal(raw, &got); err != nil {
		return false
	}
	set := make(map[string]struct{}, len(got))
	for _, e := range got {
		set[e] = struct{}{}
	}
	for _, e := range want {
		if _, ok := set[e]; !ok {
			return false
		}
		delete(set, e)
	}
	return len(set) == 0
}

// GetCRDTState returns the merged CRDT state for documentID. A document with
// no committed operations yields ErrCRDTNotFound (the caller answers 404).
//
// The merged value is derived from the per-device maxima (counter), the union
// table (gset), the version/id ordering of the accepted operations (register)
// or the live tags minus tombstones (orset), not cached: it is exactly what
// any equivalent batch order would converge to.
func (s *Store) GetCRDTState(documentID string) (CRDTState, error) {
	var docType string
	err := s.db.QueryRow(
		`SELECT type FROM crdt_documents WHERE document_id = ?`, documentID,
	).Scan(&docType)
	switch {
	case errors.Is(err, sql.ErrNoRows):
		return CRDTState{}, ErrCRDTNotFound
	case err != nil:
		return CRDTState{}, err
	}

	switch docType {
	case CRDTTypeCounter:
		var total int64
		if err := s.db.QueryRow(
			`SELECT COALESCE(SUM(value), 0) FROM crdt_counter_values WHERE document_id = ?`,
			documentID,
		).Scan(&total); err != nil {
			return CRDTState{}, err
		}
		raw, err := json.Marshal(total)
		if err != nil {
			return CRDTState{}, err
		}
		return CRDTState{Type: docType, Value: raw}, nil
	case CRDTTypeGSet:
		rows, err := s.db.Query(
			`SELECT element FROM crdt_set_elements WHERE document_id = ? ORDER BY element ASC`,
			documentID,
		)
		if err != nil {
			return CRDTState{}, err
		}
		elements := make([]string, 0)
		for rows.Next() {
			var element string
			if err := rows.Scan(&element); err != nil {
				_ = rows.Close()
				return CRDTState{}, err
			}
			elements = append(elements, element)
		}
		if err := rows.Err(); err != nil {
			_ = rows.Close()
			return CRDTState{}, err
		}
		_ = rows.Close()
		raw, err := json.Marshal(elements)
		if err != nil {
			return CRDTState{}, err
		}
		return CRDTState{Type: docType, Value: raw}, nil
	case CRDTTypeRegister:
		// A document's type row commits together with its first batch, so a
		// register document always has at least one accepted operation.
		var value []byte
		if err := s.db.QueryRow(
			`SELECT value FROM crdt_register_ops WHERE document_id = ?
			 ORDER BY version DESC, id ASC LIMIT 1`,
			documentID,
		).Scan(&value); err != nil {
			return CRDTState{}, err
		}
		return CRDTState{Type: docType, Value: json.RawMessage(value)}, nil
	case CRDTTypeORSet:
		elements, err := queryORSetElements(s.db, documentID)
		if err != nil {
			return CRDTState{}, err
		}
		raw, err := json.Marshal(elements)
		if err != nil {
			return CRDTState{}, err
		}
		return CRDTState{Type: docType, Value: raw}, nil
	default:
		return CRDTState{}, fmt.Errorf("unknown crdt type %q stored for document", docType)
	}
}

// Accepted-operation identities keep idempotency and conflict decisions
// working after compaction. Compaction trims the rows a merge derives its
// result from — superseded counter contributions, covered gset operations,
// older register versions, dead orset tags and their tombstones — but a
// re-submitted operation id must still be recognized. When a row is trimmed,
// compaction moves the only information that decision compares — the
// originating device and a digest of the type-specific comparison content —
// into crdt_op_identities. Untrimmed ids keep answering from their merge row,
// so the table holds one small fixed-size record per trimmed id, never one per
// accepted operation: it cannot grow the trimmed state back toward its
// pre-compaction footprint.
//
// The table never participates in a merge: the counter sum, the set union,
// the register winner and the live orset tags are all derived without it.

package store

import (
	"bytes"
	"crypto/sha256"
	"database/sql"
	"encoding/json"
	"errors"
	"sort"
)

// canonicalOpDigest renders the type-specific comparison content of op in a
// single canonical form and hashes it, prefixed by the type so contents of
// different types never collide. Two submissions of one id carry the same
// digest exactly when the submission layer's existing equality rules accept
// the second as idempotent:
//
//   - counter: the decoded non-negative integer (client formatting ignored);
//   - gset: the element set (order and duplicates ignored), rendered as a
//     sorted unique JSON array;
//   - register: the version together with the JSON-semantic value (1 and 1.0
//     and reordered object keys compare equal, as in jsonEqual);
//   - orset: the action and the element.
func canonicalOpDigest(docType string, op CRDTOp) ([]byte, error) {
	var content []byte
	switch docType {
	case CRDTTypeCounter:
		n, err := decodeCounterValue(op.Value)
		if err != nil {
			return nil, err
		}
		raw, err := json.Marshal(n)
		if err != nil {
			return nil, err
		}
		content = raw
	case CRDTTypeGSet:
		set := make(map[string]struct{}, len(op.Elements))
		for _, element := range op.Elements {
			set[element] = struct{}{}
		}
		elements := make([]string, 0, len(set))
		for element := range set {
			elements = append(elements, element)
		}
		sort.Strings(elements)
		raw, err := json.Marshal(elements)
		if err != nil {
			return nil, err
		}
		content = raw
	case CRDTTypeRegister:
		if op.Version < 0 {
			return nil, errors.New("register version must be a non-negative integer")
		}
		var value any
		if err := json.Unmarshal(op.Value, &value); err != nil {
			return nil, err
		}
		// Re-marshaling the decoded value canonicalizes whitespace and object
		// key order exactly the way jsonEqual compares values; wrapping it in a
		// fixed-field struct folds the version into the same canonical bytes.
		valueBytes, err := json.Marshal(value)
		if err != nil {
			return nil, err
		}
		raw, err := json.Marshal(struct {
			Version int64           `json:"version"`
			Value   json.RawMessage `json:"value"`
		}{Version: op.Version, Value: json.RawMessage(valueBytes)})
		if err != nil {
			return nil, err
		}
		content = raw
	case CRDTTypeORSet:
		if op.Action != CRDTORSetAdd && op.Action != CRDTORSetRemove {
			return nil, errors.New(`orset action must be "add" or "remove"`)
		}
		content = []byte(encodeORSetContent(op.Action, op.Element))
	default:
		return nil, errors.New("unknown crdt type")
	}

	h := sha256.New()
	_, _ = h.Write([]byte(docType))
	_, _ = h.Write([]byte{0})
	_, _ = h.Write(content)
	return h.Sum(nil), nil
}

// resolveTrimmedIdentity answers the submission-layer question for an id whose
// merge row is absent because compaction trimmed it. It returns true when the
// retained identity matches op's originating device and comparison content
// (an idempotent replay), an *ErrCRDTConflict when a retained identity exists
// but differs, and false with no error when no identity was retained (a
// genuinely new id, which proceeds through the normal acceptance path).
func resolveTrimmedIdentity(tx *sql.Tx, documentID, docType, mismatchReason string, op CRDTOp) (bool, error) {
	digest, err := canonicalOpDigest(docType, op)
	if err != nil {
		return false, &ErrCRDTConflict{ID: op.ID, Reason: err.Error()}
	}

	var existingDevice string
	var existingDigest []byte
	err = tx.QueryRow(
		`SELECT device_id, digest FROM crdt_op_identities WHERE document_id = ? AND id = ?`,
		documentID, op.ID,
	).Scan(&existingDevice, &existingDigest)
	switch {
	case errors.Is(err, sql.ErrNoRows):
		return false, nil
	case err != nil:
		return false, err
	}

	if existingDevice != op.DeviceID || !bytes.Equal(existingDigest, digest) {
		return false, &ErrCRDTConflict{ID: op.ID, Reason: mismatchReason}
	}
	return true, nil
}

// retainCRDTOpIdentity moves the comparable identity (device plus content
// digest) of one operation row compaction is about to drop into
// crdt_op_identities. A row is dropped at most once so the id is absent, but
// INSERT OR IGNORE keeps a repeat compaction finding the same row a harmless
// no-op.
func retainCRDTOpIdentity(tx *sql.Tx, documentID, docType string, op CRDTOp) error {
	digest, err := canonicalOpDigest(docType, op)
	if err != nil {
		return err
	}
	_, err = tx.Exec(
		`INSERT OR IGNORE INTO crdt_op_identities (document_id, id, device_id, digest) VALUES (?, ?, ?, ?)`,
		documentID, op.ID, op.DeviceID, digest,
	)
	return err
}

// CRDT compaction and snapshot reads bound the storage a long-lived document
// accumulates in the CRDT state layer. Merges only ever need a small part of
// the accepted history: a counter merges from each device's maximum
// contribution, a gset from the element union, a register from each device's
// latest version and the winner among them, and an orset from its live tags
// and the tombstones covering dead ones. Everything else — superseded counter
// contributions, gset operations whose elements later operations also carry,
// older register versions, tombstoned orset tags and the tombstones covering
// them — no longer affects the merged result and can be trimmed.
//
// Compaction rewrites nothing outside the CRDT tables: it never allocates a
// change cursor, never writes a change record and never notifies subscribers,
// because the merged value does not move. The trimmed state still reproduces
// the exact merge and still answers the submission layer's questions — the
// per-device counter maxima and register versions that gate regressions live
// in the retained rows, and the device plus comparison content of every
// trimmed operation id moves into the small crdt_op_identities table — so
// merge results, idempotency decisions and conflict responses are computed by
// the same rules afterward. A snapshot read reports the merged value together
// with the number of stored operations and tombstones, so a client can observe
// what compaction trimmed; both counts are non-negative and durable across
// restarts. The identity table is neither count: it holds one fixed-size
// digest per trimmed id, never participates in a merge, and cannot grow the
// trimmed state back toward its pre-compaction size.

package store

import (
	"database/sql"
	"encoding/json"
	"errors"
)

// CRDTSnapshot is a document's merged CRDT state together with the storage
// footprint of that state: Operations counts the stored operations the merge
// is derived from (counter and gset: rows of the operation log; register: the
// retained per-device operations; orset: the add tags, live or tombstoned)
// and Tombstones counts the stored orset tombstones (always zero for the
// other types). Both counts are non-negative; compaction drives them down to
// the operations and tombstones that still participate in the merge.
type CRDTSnapshot struct {
	Type       string          // the document's fixed CRDT type
	Value      json.RawMessage // the merged value, exactly as GetCRDTState derives it
	Operations int64           // stored operations the merge is derived from
	Tombstones int64           // stored orset tombstones; 0 for counter, gset and register
}

// CompactCRDT trims every stored operation and tombstone that no longer
// affects the document's merged result, in one serialized transaction, and
// returns the post-compaction snapshot (byte-for-byte what a snapshot read
// returns immediately afterward).
//
// The registration/permission layer is enforced exactly as in SubmitCRDTOps
// and before any CRDT content is observed: an unregistered device yields
// ErrDeviceNotFound and a revoked device yields ErrPermissionDenied, and
// neither touches any state. A document with no committed CRDT operation
// yields ErrCRDTNotFound. Any failure leaves the state untouched.
//
// Per type, compaction keeps precisely the rows the merge and the submission
// checks still read:
//
//   - counter: each device's maximum contribution (ties keep the
//     lexicographically smaller operation id); superseded contributions are
//     dropped. The per-device maxima table is untouched, so monotonicity
//     checks and the merged sum are unchanged. Each dropped id keeps a
//     device-plus-value identity.
//   - gset: a minimal prefix cover of the union — operations are considered
//     in ascending id order and one is kept only when it contributes an
//     element no previously kept operation covers. The union table is
//     untouched, so the merged set is unchanged. Each dropped id keeps a
//     device-plus-elements identity.
//   - register: each device's greatest-version operation (which includes the
//     document's winner). Regression checks derive per-device maxima from
//     these rows, so later version checks and the winning value are
//     unchanged. Each dropped older id keeps a device-plus-version-plus-value
//     identity.
//   - orset: live add tags. Tombstoned tags are dropped together with the
//     tombstones covering them — a dead tag and its tombstone cancel out of
//     the merge — so the live element set is unchanged. The operation log is
//     untouched (adds and removes alike), so replaying either one stays
//     idempotent and a replayed remove never tombstones tags that arrived
//     after it; no identity row is needed.
//
// Compaction is idempotent: a second run finds nothing to trim and returns
// the same snapshot. It commits no change-log row, allocates no cursor and,
// because the merged value never moves, notifies no subscriber.
func (s *Store) CompactCRDT(documentID, deviceID string) (CRDTSnapshot, error) {
	// Serialize with submissions and other compactions: the trim and the
	// submission checks read the same rows, so they must not interleave.
	s.crdtMu.Lock()
	defer s.crdtMu.Unlock()

	tx, err := s.db.Begin()
	if err != nil {
		return CRDTSnapshot{}, err
	}
	defer func() { _ = tx.Rollback() }()

	// Registration and permission are enforced before any CRDT content is
	// observed, so a rejected compaction cannot reveal type or state.
	var deviceExists bool
	if err := tx.QueryRow(
		`SELECT EXISTS(SELECT 1 FROM devices WHERE id = ?)`, deviceID,
	).Scan(&deviceExists); err != nil {
		return CRDTSnapshot{}, err
	}
	if !deviceExists {
		return CRDTSnapshot{}, ErrDeviceNotFound
	}
	var storedAuth int
	err = tx.QueryRow(
		`SELECT authorized FROM document_permissions WHERE document_id = ? AND device_id = ?`,
		documentID, deviceID,
	).Scan(&storedAuth)
	switch {
	case errors.Is(err, sql.ErrNoRows):
		// No deviation row: devices start authorized.
	case err != nil:
		return CRDTSnapshot{}, err
	default:
		if storedAuth == 0 {
			return CRDTSnapshot{}, ErrPermissionDenied
		}
	}

	var docType string
	err = tx.QueryRow(
		`SELECT type FROM crdt_documents WHERE document_id = ?`, documentID,
	).Scan(&docType)
	switch {
	case errors.Is(err, sql.ErrNoRows):
		return CRDTSnapshot{}, ErrCRDTNotFound
	case err != nil:
		return CRDTSnapshot{}, err
	}

	switch docType {
	case CRDTTypeCounter:
		if err := compactCounterOps(tx, documentID); err != nil {
			return CRDTSnapshot{}, err
		}
	case CRDTTypeGSet:
		if err := compactGSetOps(tx, documentID); err != nil {
			return CRDTSnapshot{}, err
		}
	case CRDTTypeRegister:
		if err := compactRegisterOps(tx, documentID); err != nil {
			return CRDTSnapshot{}, err
		}
	case CRDTTypeORSet:
		if err := compactORSetOps(tx, documentID); err != nil {
			return CRDTSnapshot{}, err
		}
	}

	if err := tx.Commit(); err != nil {
		return CRDTSnapshot{}, err
	}
	// The commit is durable and crdtMu is still held, so no submission or
	// compaction can interleave before this read: the returned snapshot is
	// exactly what a snapshot read immediately afterward observes.
	return s.GetCRDTSnapshot(documentID)
}

// compactCounterOps drops every counter operation superseded by a greater (or
// equal but later-id) contribution from the same device, keeping exactly one
// operation per device: its maximum contribution, ties broken by the
// lexicographically smaller operation id. The per-device maxima table that
// drives the merge and the regression checks is untouched. Before a row is
// dropped its identity is retained, so a replay of the trimmed id stays
// idempotent and a mismatched replay stays a conflict.
func compactCounterOps(tx *sql.Tx, documentID string) error {
	rows, err := tx.Query(
		`SELECT id, device_id, value FROM crdt_ops WHERE document_id = ? ORDER BY id ASC`,
		documentID,
	)
	if err != nil {
		return err
	}
	type contribution struct {
		id    string
		value int64
		raw   []byte
	}
	best := make(map[string]contribution)
	var drop []CRDTOp
	for rows.Next() {
		var id, deviceID string
		var raw []byte
		if err := rows.Scan(&id, &deviceID, &raw); err != nil {
			_ = rows.Close()
			return err
		}
		value, err := decodeCounterValue(raw)
		if err != nil {
			_ = rows.Close()
			return err
		}
		// Ids arrive in ascending order, so the first contribution seen at the
		// device's maximum value carries the smallest id; only a strictly
		// greater value replaces it.
		if cur, ok := best[deviceID]; !ok || value > cur.value {
			if ok {
				drop = append(drop, CRDTOp{ID: cur.id, DeviceID: deviceID, Value: json.RawMessage(cur.raw)})
			}
			best[deviceID] = contribution{id: id, value: value, raw: raw}
		} else {
			drop = append(drop, CRDTOp{ID: id, DeviceID: deviceID, Value: json.RawMessage(raw)})
		}
	}
	if err := rows.Err(); err != nil {
		_ = rows.Close()
		return err
	}
	_ = rows.Close()

	for _, op := range drop {
		if err := retainCRDTOpIdentity(tx, documentID, CRDTTypeCounter, op); err != nil {
			return err
		}
		if _, err := tx.Exec(
			`DELETE FROM crdt_ops WHERE document_id = ? AND id = ?`,
			documentID, op.ID,
		); err != nil {
			return err
		}
	}
	return nil
}

// compactGSetOps drops every gset operation whose elements are all covered by
// kept operations: operations are considered in ascending id order and one is
// kept only when it contributes at least one element no previously kept
// operation covers. The union table that drives the merge is untouched, so
// the kept operations still reproduce the exact merged set. A dropped
// operation's identity is retained before its row is deleted, so a replay of
// the trimmed id stays idempotent and a mismatched replay stays a conflict.
func compactGSetOps(tx *sql.Tx, documentID string) error {
	rows, err := tx.Query(
		`SELECT id, device_id, value FROM crdt_ops WHERE document_id = ? ORDER BY id ASC`,
		documentID,
	)
	if err != nil {
		return err
	}
	covered := make(map[string]struct{})
	var drop []CRDTOp
	for rows.Next() {
		var id, deviceID string
		var raw []byte
		if err := rows.Scan(&id, &deviceID, &raw); err != nil {
			_ = rows.Close()
			return err
		}
		var elements []string
		if err := json.Unmarshal(raw, &elements); err != nil {
			_ = rows.Close()
			return err
		}
		keeps := false
		for _, element := range elements {
			if _, ok := covered[element]; !ok {
				keeps = true
				covered[element] = struct{}{}
			}
		}
		if !keeps {
			drop = append(drop, CRDTOp{ID: id, DeviceID: deviceID, Elements: elements})
		}
	}
	if err := rows.Err(); err != nil {
		_ = rows.Close()
		return err
	}
	_ = rows.Close()

	for _, op := range drop {
		if err := retainCRDTOpIdentity(tx, documentID, CRDTTypeGSet, op); err != nil {
			return err
		}
		if _, err := tx.Exec(
			`DELETE FROM crdt_ops WHERE document_id = ? AND id = ?`,
			documentID, op.ID,
		); err != nil {
			return err
		}
	}
	return nil
}

// compactRegisterOps drops every register operation superseded by a greater
// version from the same device, keeping each device's greatest-version
// operation. Versions strictly increase per device, so exactly one row per
// device survives; the per-device maxima the regression checks derive from
// the table, and the document's winning value, are unchanged. A dropped
// operation's identity is retained before its row is deleted, so a replay of
// the trimmed id stays idempotent and a mismatched replay stays a conflict.
func compactRegisterOps(tx *sql.Tx, documentID string) error {
	rows, err := tx.Query(
		`SELECT id, device_id, version, value FROM crdt_register_ops
		 WHERE document_id = ?
		   AND EXISTS (
			SELECT 1 FROM crdt_register_ops newer
			WHERE newer.document_id = crdt_register_ops.document_id
			  AND newer.device_id = crdt_register_ops.device_id
			  AND newer.version > crdt_register_ops.version
		   )`,
		documentID,
	)
	if err != nil {
		return err
	}
	var drop []CRDTOp
	for rows.Next() {
		var op CRDTOp
		if err := rows.Scan(&op.ID, &op.DeviceID, &op.Version, &op.Value); err != nil {
			_ = rows.Close()
			return err
		}
		drop = append(drop, op)
	}
	if err := rows.Err(); err != nil {
		_ = rows.Close()
		return err
	}
	_ = rows.Close()

	for _, op := range drop {
		if err := retainCRDTOpIdentity(tx, documentID, CRDTTypeRegister, op); err != nil {
			return err
		}
		if _, err := tx.Exec(
			`DELETE FROM crdt_register_ops WHERE document_id = ? AND id = ?`,
			documentID, op.ID,
		); err != nil {
			return err
		}
	}
	return nil
}

// compactORSetOps drops every tombstoned add tag together with every
// tombstone: a dead tag and the tombstone covering it cancel out of the
// merge, so the live element set is unchanged. The operation log is
// untouched, so replaying an add or a remove stays idempotent and a replayed
// remove never tombstones tags accepted after it.
func compactORSetOps(tx *sql.Tx, documentID string) error {
	if _, err := tx.Exec(
		`DELETE FROM crdt_orset_tags
		 WHERE document_id = ?
		   AND EXISTS (
			SELECT 1 FROM crdt_orset_tombstones x
			WHERE x.document_id = crdt_orset_tags.document_id
			  AND x.element = crdt_orset_tags.element
			  AND x.op_id = crdt_orset_tags.op_id
		   )`,
		documentID,
	); err != nil {
		return err
	}
	_, err := tx.Exec(
		`DELETE FROM crdt_orset_tombstones WHERE document_id = ?`,
		documentID,
	)
	return err
}

// GetCRDTSnapshot returns the document's merged CRDT state together with the
// number of stored operations and tombstones the merge is derived from. A
// document with no committed operations yields ErrCRDTNotFound (the caller
// answers 404). The read is pure: it advances no cursor, writes nothing and
// registers no subscription.
func (s *Store) GetCRDTSnapshot(documentID string) (CRDTSnapshot, error) {
	state, err := s.GetCRDTState(documentID)
	if err != nil {
		return CRDTSnapshot{}, err
	}
	snapshot := CRDTSnapshot{Type: state.Type, Value: state.Value}

	count := func(query string) (int64, error) {
		var n int64
		if err := s.db.QueryRow(query, documentID).Scan(&n); err != nil {
			return 0, err
		}
		return n, nil
	}

	switch state.Type {
	case CRDTTypeCounter, CRDTTypeGSet:
		operations, err := count(`SELECT COUNT(*) FROM crdt_ops WHERE document_id = ?`)
		if err != nil {
			return CRDTSnapshot{}, err
		}
		snapshot.Operations = operations
	case CRDTTypeRegister:
		operations, err := count(`SELECT COUNT(*) FROM crdt_register_ops WHERE document_id = ?`)
		if err != nil {
			return CRDTSnapshot{}, err
		}
		snapshot.Operations = operations
	case CRDTTypeORSet:
		operations, err := count(`SELECT COUNT(*) FROM crdt_orset_tags WHERE document_id = ?`)
		if err != nil {
			return CRDTSnapshot{}, err
		}
		tombstones, err := count(`SELECT COUNT(*) FROM crdt_orset_tombstones WHERE document_id = ?`)
		if err != nil {
			return CRDTSnapshot{}, err
		}
		snapshot.Operations = operations
		snapshot.Tombstones = tombstones
	}
	return snapshot, nil
}

package server

import (
	"context"
	"encoding/json"
	"errors"
	"io"
	"log"
	"mime"
