	// raced the registration is honored before anything is sent.
	if closingOnly() {
		return
	}
	if initial != nil {
		if !send(*initial) {
			return
		}
	}

	for {
		if endNow() {
			return
		}

		// Drain every committed state queued since the last park, in commit
		// order; a revoke or termination is honored between frames.
		for _, state := range sub.Drain() {
			if endNow() {
				return
			}
			if !send(state) {
				return
			}
		}
		if endNow() {
			return
		}

		select {
		case <-sub.Wake():
			// A coalescing "drain now" signal; loop and flush the whole queue.
		case <-sub.Revoked():
			if s.Closing() {
				endSubscription(conn, clientGone, wsCloseGoingAway, "going away")
				return
			}
			endSubscription(conn, clientGone, wsClosePermissionRevoked, "permission revoked")
			return
		case <-clientGone:
			return
		case <-r.Context().Done():
			return
		}
	}
}

// encodeCRDTStateFrame renders one state message exactly as the state read
// endpoints render their bodies: the shared encoder (HTML escaping included,
// map keys sorted to type then value) and the same trailing newline, so a
// pushed frame can be compared byte-for-byte with a GET .../crdt/state
// response at either the document or session path.
func encodeCRDTStateFrame(state store.CRDTState) []byte {
	return marshalCRDTState(state)
}

package server

import (
	"encoding/json"
	"errors"
	"net/http"
	"time"

	"github.com/alicegogogogogo/local-first-sync-service/internal/store"
)

// subscribePageLimit is the page size used while replaying changes already
// committed after the subscription cursor. It matches the largest page the
// paginated read endpoint accepts, so catch-up and reads stay page-aligned.
const subscribePageLimit = 1000

// wsCloseEchoWait bounds how long a server-initiated close waits for the
// client's close echo before the deferred TCP teardown.
const wsCloseEchoWait = 500 * time.Millisecond

// handleSubscribe is the WebSocket document subscription mounted under the
// session view:
//
//	GET /v1/sessions/{sessionId}/documents/{documentId}/changes/subscribe?cursor=N
//
// The subscription identity is entirely the existing session: the session's
// owning device is the only credential. Validation happens entirely before
// the 101 handshake and writes nothing:
//
//  1. cursor must be a non-negative decimal integer (400 JSON otherwise),
//  2. the request must carry a valid WebSocket upgrade handshake (400 JSON),
//  3. the session must currently exist (404 JSON),
//  4. its device must currently hold permission for the document (403 JSON).
//
// After the upgrade the server first sends every committed change with a
// cursor greater than the starting cursor — paged in cursor order, one text
// frame per record in the exact {"id","deviceId","payload","cursor"} shape of
// a paginated read row — then seamlessly continues with changes committed by
// any write path (batch post, merge, restore, replay). Frames are never
// reordered or coalesced; a later read from the last observed cursor returns
// the same rows. The connection is push-only: inbound data frames are read
// and discarded, only close/ping control frames are honored.
//
// A permission revoked after the upgrade ends the subscription with close
// code 4403 and no further frame follows; a termination signal ends every
// subscription with 1001. A client disconnect simply unregisters — like long
// polling, a subscription writes no change, cursor or other record.
func handleSubscribe(s *store.Store, w http.ResponseWriter, r *http.Request) {
	sessionID := r.PathValue("sessionId")   // route pattern + guard guarantee non-empty
	documentID := r.PathValue("documentId") // route pattern + guard guarantee non-empty

	// Parameter shape first: a bad cursor is a 400 even when the session or
	// handshake is also bad, matching the session-scoped read ordering.
	cursor, ok := parseSubscribeCursor(w, r)
	if !ok {
		return
	}
	if !checkWebSocketUpgrade(r) {
		writeError(w, http.StatusBadRequest, "a WebSocket upgrade handshake is required")
		return
	}

	deviceID, err := s.SessionDevice(sessionID)
	if err != nil {
		if errors.Is(err, store.ErrSessionNotFound) {
			writeError(w, http.StatusNotFound, "session not found")
			return
		}
		writeError(w, http.StatusInternalServerError, "failed to look up session")
		return
	}
	authorized, err := s.DocumentAuthorized(documentID, deviceID)
	if err != nil {
		writeError(w, http.StatusInternalServerError, "failed to look up permission")
		return
	}
	if !authorized {
		writeError(w, http.StatusForbidden, "device permission for this document has been revoked")
		return
	}

	conn, err := upgradeWebSocket(w, r)
	if err != nil {
		// The 101 response could not be written and the connection has been
		// hijacked (or is gone), so no JSON error can be produced. Nothing
		// was registered or written to the store.
		return
	}

	serveSubscription(r, s, conn, documentID, deviceID, cursor)
}

// parseSubscribeCursor validates the mandatory cursor query parameter: it
// must be present and a decimal non-negative integer. Negative, fractional
// and non-numeric values are a 400 JSON error; signs and adornments are
// rejected.
func parseSubscribeCursor(w http.ResponseWriter, r *http.Request) (int64, bool) {
	raw := r.URL.Query().Get("cursor")
	// parseCursorPath accepts only decimal digits (no sign, fraction or
	// exponent); a missing parameter is an empty raw and is rejected too.
	cursor, ok := parseCursorPath(raw)
	if !ok {
		writeError(w, http.StatusBadRequest, "cursor must be a non-negative integer")
		return 0, false
	}
	return cursor, true
}

// serveSubscription runs one upgraded connection to completion. It registers
// before the first log read (a commit landing during catch-up is therefore
// never missed), then alternates a flush phase — drain every page of changes
// past the last sent cursor — and a park phase on the wake channel. A revoke
// is acted on only after the committed tail is flushed, so a commit that was
// authorized when it landed is still delivered ahead of the 4403. The method
// returns when the client leaves, permission is revoked or the store starts
// closing; the hijacked connection is closed on exit.
func serveSubscription(r *http.Request, s *store.Store, conn *wsConn, documentID, deviceID string, cursor int64) {
	// Registration precedes the first read: the wake channel is buffered, so
	// a commit during a read leaves a pending wake that makes the next park
	// return immediately — no wake is lost. The revoked channel closes once
	// if access is withdrawn, and that event survives a racing re-grant.
	wakeCh, revokedCh, unregister := s.AddSubscription(documentID, deviceID)
	defer func() {
		unregister()
		_ = conn.NetClose()
	}()

	clientGone := make(chan struct{})
	go func() {
		defer close(clientGone)
		for {
			if _, _, err := conn.ReadMessage(); err != nil {
				// A malformed frame ends the connection with the RFC
				// protocol-error code; a client close is already echoed
				// inside ReadMessage; a network drop needs no frame.
				var protoErr *wsProtocolErrorString
				if errors.As(err, &protoErr) {
					_ = conn.Close(wsCloseProtocolError, "protocol error")
				}
				return
			}
			// Push-only channel: an inbound data frame is read and
			// discarded; the client cannot mutate the log over it.
		}
	}()

	// checkEnd non-blockingly maps a closing store to 1001 and a sticky
	// revoke to 4403; it returns true when the subscription must end. A
	// termination signal takes precedence: SIGTERM must end every
	// subscription with 1001 even if a revoke is also pending.
	checkEnd := func() bool {
		if s.Closing() {
			endSubscription(conn, clientGone, wsCloseGoingAway, "going away")
			return true
		}
		select {
		case <-revokedCh:
			endSubscription(conn, clientGone, wsClosePermissionRevoked, "permission revoked")
			return true
		default:
		}
		return false
	}

	position := cursor
	first := true
	for {
		if !first {
			// Park until a commit, a sticky revoke or the termination signal
			// wakes us. r.Context() covers a non-shutdown cancel; the read
			// pump covers a client disconnect.
			select {
			case <-wakeCh:
				// Drain any coalesced follow-up signal as well; the flush
				// below reconciles every case by re-reading from the last
				// sent cursor.
				select {
				case <-wakeCh:
				default:
				}
			case <-revokedCh:
				if s.Closing() {
					endSubscription(conn, clientGone, wsCloseGoingAway, "going away")
					return
				}
				endSubscription(conn, clientGone, wsClosePermissionRevoked, "permission revoked")
				return
			case <-clientGone:
				return
			case <-r.Context().Done():
				return
			}
			if s.Closing() {
				endSubscription(conn, clientGone, wsCloseGoingAway, "going away")
				return
			}
		}
		first = false

		// Flush phase: page every change past position in cursor order. A
		// termination signal or a revoke is honored between pages/rows so a
		// large catch-up cannot delay the closing frame. A revoke arriving
		// while the final already-authorized tail is in flight is checked
		// after the inner loop, so that tail still goes out first.
		for {
			if checkEnd() {
				return
			}
			select {
			case <-clientGone:
				return
			case <-r.Context().Done():
				return
			default:
			}

			changes, _, err := s.ListChanges(documentID, position, subscribePageLimit)
			if err != nil {
				_ = conn.Close(wsCloseInternalError, "internal error")
				return
			}
			for i := range changes {
				if checkEnd() {
					return
				}
				raw, marshalErr := json.Marshal(changes[i])
				if marshalErr != nil {
					_ = conn.Close(wsCloseInternalError, "internal error")
					return
				}
				if writeErr := conn.WriteText(raw); writeErr != nil {
					return
				}
				position = changes[i].Cursor
			}
			if len(changes) < subscribePageLimit {
				break
			}
		}

		// Caught up. A revoke that arrived during the last page (its tail was
		// just flushed) now ends the subscription; otherwise loop and park.
		// Closing still wins over a pending revoke.
		if checkEnd() {
			return
		}
	}
}

// endSubscription sends the mandated closing frame and briefly waits for the
// read pump to observe the peer's close echo, so a graceful close reaches the
// client instead of being truncated by the deferred TCP teardown. It returns
// promptly if the peer is already gone; the caller's deferred NetClose drops
// the socket either way.
func endSubscription(conn *wsConn, clientGone <-chan struct{}, code int, reason string) {
	_ = conn.Close(code, reason)
	timer := time.NewTimer(wsCloseEchoWait)
	defer timer.Stop()
	select {
	case <-clientGone:
	case <-timer.C:
	}
}

// Package service wires the HTTP surface and the durable store into one
// process: strict address binding, database open, a one-way readiness gate,
// actual-endpoint reporting and graceful shutdown.
//
// Startup order is deliberately load-bearing: the requested address is
// validated and bound first (so a fixed port that clashes fails before
// anything else happens, and :0 lets the kernel allocate one), and only after
// the database at the configured path has been created and opened does the
// instance become ready and print its endpoint. A failure at any step closes
// what was already acquired and returns an error, so no half-ready service is
// left behind. Two processes with different SYNC_ADDR/SYNC_DATA pairs share
// neither listener nor database.
package service

import (
	"context"
	"errors"
	"fmt"
	"log"
	"net"
	"net/http"
	"os"
	"path/filepath"
	"strconv"
	"sync/atomic"
	"time"

	"github.com/alicegogogogogo/local-first-sync-service/internal/server"
	"github.com/alicegogogogogo/local-first-sync-service/internal/store"
)

const (
	// defaultAddr is used only when SYNC_ADDR is unset.
	defaultAddr = "127.0.0.1:8080"
	// defaultDataPath is used only when SYNC_DATA is unset.
	defaultDataPath = "data/sync.db"

	readHeaderTimeout = 10 * time.Second
	shutdownTimeout   = 10 * time.Second
)

// Options configures one isolated service instance.
type Options struct {
	// Addr is the host:port to bind (SYNC_ADDR). Empty selects defaultAddr.
	// A fixed address binds exactly that address with no fallback; port 0
	// asks the kernel for a free port, reported through OnReady and the log.
	Addr string
	// DataPath is the SQLite database path (SYNC_DATA). Empty selects
	// defaultDataPath; parent directories are created as needed.
	DataPath string
	// Logger receives the one startup line and shutdown diagnostics. nil
	// uses the standard logger.
	Logger *log.Logger
	// OnReady, if set, is invoked with the actual dialable host:port after
	// the listener is bound, the database is open and readiness is on.
	OnReady func(actualAddr string)
}

// Run starts one instance and blocks until ctx is canceled, then stops
// accepting new requests, drains in-flight ones and closes the database. A
// startup failure (bad address, port already in use, data directory or
// database that cannot be created or opened) returns before the instance is
// ready with every acquired resource already released.
func Run(ctx context.Context, opts Options) error {
	addr := opts.Addr
	if addr == "" {
		addr = defaultAddr
	}
	dataPath := opts.DataPath
	if dataPath == "" {
		dataPath = defaultDataPath
	}
	logger := opts.Logger
	if logger == nil {
		logger = log.Default()
	}

	// Validate first: a malformed SYNC_ADDR exits here, before any data
	// directory is created or store opened, and never falls back.
	host, _, err := parseAddr(addr)
	if err != nil {
		return err
	}

	// Bind before opening the database. A fixed port that is already taken
	// fails here with no files touched; :0 resolves to the allocated port.
	ln, err := net.Listen("tcp", addr)
	if err != nil {
		return fmt.Errorf("listen on %s: %w", addr, err)
	}
	tcpAddr, ok := ln.Addr().(*net.TCPAddr)
	if !ok {
		_ = ln.Close()
		return fmt.Errorf("listener on %s reported unexpected address %v", addr, ln.Addr())
	}
	// Report an address a client can actually dial. An empty host means the
	// request was a wildcard bind (":port"); loopback always reaches it.
	displayHost := host
	if displayHost == "" {
		displayHost = "127.0.0.1"
	}
	actualAddr := net.JoinHostPort(displayHost, strconv.Itoa(tcpAddr.Port))

	if dir := filepath.Dir(dataPath); dir != "." {
		if err := os.MkdirAll(dir, 0o755); err != nil {
			_ = ln.Close()
			return fmt.Errorf("create data directory %q: %w", dir, err)
		}
	}
	st, err := store.Open(dataPath)
	if err != nil {
		_ = ln.Close()
		return fmt.Errorf("open store at %q: %w", dataPath, err)
	}

	// The gate covers the whole surface, /healthz included: nothing answers
	// success until the database is open and the listener is serving.
	var ready atomic.Bool
	srv := &http.Server{
		Handler:           server.NewHandlerWithReadiness(st, ready.Load),
		ReadHeaderTimeout: readHeaderTimeout,
	}
	serveErr := make(chan error, 1)
	go func() {
		serveErr <- srv.Serve(ln)
	}()

	ready.Store(true)
	logger.Printf("sync service listening on %s (data: %s)", actualAddr, dataPath)
	if opts.OnReady != nil {
		opts.OnReady(actualAddr)
	}

	// Block until shutdown is requested or the listener dies on its own.
	var serveResult error
	stoppedGracefully := false
	select {
	case <-ctx.Done():
		stoppedGracefully = true
	case serveResult = <-serveErr:
	}

	// Shutdown closes the listener immediately (new connections are refused)
	// and lets in-flight handlers finish before the store is closed. Waiting
	// long polls are interrupted first so they answer instead of pinning the
	// drain until their wait deadline. It is safe even when Serve has already
	// returned on its own.
	st.InterruptWaits()
	shutdownCtx, cancel := context.WithTimeout(context.Background(), shutdownTimeout)
	defer cancel()
	if err := srv.Shutdown(shutdownCtx); err != nil && !errors.Is(err, http.ErrServerClosed) {
		logger.Printf("graceful shutdown did not complete: %v; forcing connections closed", err)
		_ = srv.Close()
	}
	if stoppedGracefully {
		serveResult = <-serveErr
	}

	if serveResult != nil && !errors.Is(serveResult, http.ErrServerClosed) {
		_ = st.Close()
		return fmt.Errorf("serve on %s: %w", actualAddr, serveResult)
	}
	if err := st.Close(); err != nil {
		// Shutdown was requested and all handlers have drained; report the
		// close problem without pretending requests were lost.
		logger.Printf("close store at %q: %v", dataPath, err)
	}
	return nil
}

// parseAddr validates that addr is a host:port with a TCP port in range. Port
// 0 is legal and means "let the kernel choose". Anything else is a startup
// error rather than a cue to fall back to a default.
func parseAddr(addr string) (host string, port int, err error) {
	host, portStr, splitErr := net.SplitHostPort(addr)
	if splitErr != nil {
		return "", 0, fmt.Errorf("invalid SYNC_ADDR %q: expected host:port: %v", addr, splitErr)
	}
	port, convErr := strconv.Atoi(portStr)
	if convErr != nil || port < 0 || port > 65535 {
		return "", 0, fmt.Errorf("invalid SYNC_ADDR %q: port must be an integer between 0 and 65535", addr)
	}
	return host, port, nil
}

package main

import (
	"context"
	"log"
	"os"
	"os/signal"
	"syscall"

	"github.com/alicegogogogogo/local-first-sync-service/internal/service"
)

func main() {
	ctx, stop := signal.NotifyContext(context.Background(), syscall.SIGINT, syscall.SIGTERM)
	defer stop()

	err := service.Run(ctx, service.Options{
		Addr:     os.Getenv("SYNC_ADDR"),
		DataPath: os.Getenv("SYNC_DATA"),
	})
	if err != nil {
		// A startup or serving failure ends the process non-zero with the
		// cause intact; a signal-triggered shutdown returns nil.
		log.Fatal(err)
	}
}

package store

import (
	"crypto/sha256"
	"database/sql"
	"encoding/hex"
	"errors"
	"fmt"
)

// ErrAttachmentNotFound reports that no attachment exists with the given id.
// The caller maps it to 404.
var ErrAttachmentNotFound = errors.New("attachment not found")

// ErrAttachmentForbidden reports that the device in the path is not the
// device that created the attachment. The caller maps it to 403.
var ErrAttachmentForbidden = errors.New("attachment belongs to another device")

// ErrAttachmentIncomplete reports that a finish was attempted before every
// chunk arrived, or the received bytes do not add up to the declared total.
// The upload stays resumable; the caller maps it to 409.
var ErrAttachmentIncomplete = errors.New("attachment chunks are missing or shorter than the declared total")

// ErrAttachmentDigestMismatch reports that the assembled content does not
// hash to the declared digest. The attachment stays incomplete; the caller
// maps it to 422.
var ErrAttachmentDigestMismatch = errors.New("assembled content does not match the declared sha256")

// ErrAttachmentDigestConflict reports that a different-size completed content
// already exists under the same digest, so this upload cannot be finished or
// reused. The upload stays resumable; the caller maps it to 409.
var ErrAttachmentDigestConflict = errors.New("a completed content with the same digest but a different size exists")

// ErrAttachmentConflict reports that an attachment id is already taken — by
// another device, or by this device with different metadata. The original
// record is unchanged; the caller maps it to 409.
type ErrAttachmentConflict struct {
	ID string
}

func (e *ErrAttachmentConflict) Error() string {
	return fmt.Sprintf("attachment %q already exists with different owner or metadata", e.ID)
}

// ErrAttachmentSealed reports a chunk write to an upload that was already
// finished. A sealed attachment is immutable: every further chunk write —
// even a byte-identical resubmission — is rejected and the recorded state and
// content are left unchanged. The caller maps it to 409.
var ErrAttachmentSealed = errors.New("attachment is complete and no longer accepts chunks")

// ErrChunkInvalid reports a chunk that violates the upload's declared shape:
// an out-of-range index, a non-final chunk shorter than the declared chunk
// size, or a final chunk beyond the declared total. The caller maps it to
// 400; nothing is written.
type ErrChunkInvalid struct {
	Reason string
}

func (e *ErrChunkInvalid) Error() string { return e.Reason }

