### permission/permission.go

```go
// Package permission is the document-permission service: it persists the
// per-(document, device) authorization state and is the single place that
// decides whether a device currently holds permission for a document.
//
// Every (document, device) pair starts authorized; a row records a deviation
// from that default. Writes are serialized in one transaction and committed
// to disk, so concurrent grant/revoke calls each land as a complete state and
// survive a restart. Revoking never deletes anything outside this service's
// own table; other services enforce the decision through CheckTx (inside
// their own serialized transactions) and learn about revocations through the
// OnRevoke hooks.
//
// The service owns exactly one table (document_permissions) and never reads
// or writes any other service's storage: the registration-layer device check
// it enforces on writes goes through the DeviceRegistry interface it is
// constructed with.
package permission

import (
    "database/sql"
    "errors"
    "sync"
)

// ErrPermissionDenied reports that a device's access to the document has been
// revoked. Callers map it to 403; nothing is written and no content is
// exposed.
var ErrPermissionDenied = errors.New("device permission for this document has been revoked")

// DeviceRegistry is the registration-layer boundary the service consults
// before recording a permission change: RequireTx must return a non-nil
// error (propagated verbatim to the caller) when deviceID is not a
// registered device. The check runs inside the service's own serialized
// transaction.
type DeviceRegistry interface {
    RequireTx(tx *sql.Tx, deviceID string) error
}

// schema is the service's own table; no other service reads or writes it.
const schema = `
CREATE TABLE IF NOT EXISTS document_permissions (
    document_id TEXT NOT NULL,
    device_id   TEXT NOT NULL,
    authorized  INTEGER NOT NULL,
    PRIMARY KEY (document_id, device_id)
);
`

// Service persists and decides document permissions.
type Service struct {
    db       *sql.DB
    registry DeviceRegistry

    mu      sync.Mutex
    revokeHooks []func(documentID, deviceID string)
}

// New opens the service on db, creating its table if needed. registry may be
// nil, in which case writes skip the device-existence check (useful when the
// service is embedded without a registration layer).
func New(db *sql.DB, registry DeviceRegistry) (*Service, error) {
    if _, err := db.Exec(schema); err != nil {
        return nil, err
    }
    return &Service{db: db, registry: registry}, nil
}

// OnRevoke registers a hook fired synchronously, after the commit, each time
// a revoke actually changes a (document, device) pair from authorized to
// revoked. Hooks are the service's only notification channel: it neither
// knows nor touches any subscriber registry.
func (s *Service) OnRevoke(hook func(documentID, deviceID string)) {
    s.mu.Lock()
    defer s.mu.Unlock()
    s.revokeHooks = append(s.revokeHooks, hook)
}

// Set grants or revokes deviceID's access to documentID and reports whether
// the stored permission actually changed. ...
func (s *Service) Set(documentID, deviceID string, authorized bool) (changed bool, err error) {
    tx, err := s.db.Begin()
    ...
    if s.registry != nil {
        if err := s.registry.RequireTx(tx, deviceID); err != nil {
            return false, err
        }
    }
    current := true
    var stored int
    err = tx.QueryRow(`SELECT authorized FROM document_permissions WHERE document_id = ? AND device_id = ?`, documentID, deviceID).Scan(&stored)
    switch {
    case errors.Is(err, sql.ErrNoRows):
    case err != nil:
        return false, err
    default:
        current = stored != 0
    }
    if current == authorized {
        return false, tx.Commit()
    }
    v := 0
    if authorized { v = 1 }
    if _, err := tx.Exec(`INSERT ... ON CONFLICT ...`, ...); err != nil { return false, err }
    if err := tx.Commit(); err != nil { return false, err }
    if !authorized {
        s.fireRevoke(documentID, deviceID)
    }
    return true, nil
}

func (s *Service) fireRevoke(documentID, deviceID string) {
    s.mu.Lock()
    hooks := append([]func(string, string){}, s.revokeHooks...)
    s.mu.Unlock()
    for _, hook := range hooks {
        hook(documentID, deviceID)
    }
}

// Authorized reports whether deviceID currently holds permission for
// documentID. Devices start authorized, so an absent row means authorized.
func (s *Service) Authorized(documentID, deviceID string) (bool, error) { ... }

// CheckTx is the unified revoke decision other services enforce inside their
// own serialized transactions: it returns ErrPermissionDenied when the pair
// is currently revoked and nil otherwise. It reads only this service's table.
func (s *Service) CheckTx(tx *sql.Tx, documentID, deviceID string) error {
    var stored int
    err := tx.QueryRow(`SELECT authorized FROM document_permissions WHERE document_id = ? AND device_id = ?`, documentID, deviceID).Scan(&stored)
    switch {
    case errors.Is(err, sql.ErrNoRows):
        return nil
    case err != nil:
        return err
    default:
        if stored == 0 { return ErrPermissionDenied }
        return nil
    }
}
```

