package crdtstate

// GetSnapshot returns the document's merged CRDT state together with the
// number of stored operations and tombstones the merge is derived from. A
// document with no committed operations yields ErrNotFound (the caller
// answers 404). The read is pure: it advances no cursor, writes nothing and
// registers no subscription.
func (s *Service) GetSnapshot(documentID string) (Snapshot, error) {
	state, err := s.GetState(documentID)
	if err != nil {
		return Snapshot{}, err
	}
	return s.snapshotFrom(state, s.db, documentID)
}

// snapshotLocked is GetSnapshot's post-compaction twin: the service lock is
// already held, so the snapshot is computed without re-locking and no
// submission or compaction can interleave before it.
func (s *Service) snapshotLocked(documentID string) (Snapshot, error) {
	state, err := s.GetState(documentID)
	if err != nil {
		return Snapshot{}, err
	}
	return s.snapshotFrom(state, s.db, documentID)
}

// snapshotFrom derives the storage footprint counts for an already-loaded
// merged state. q is satisfied by both *sql.DB (a snapshot read) and *sql.Tx
// (a transactional read), so the counting queries exist exactly once.
func (s *Service) snapshotFrom(state State, q orsetQuerier, documentID string) (Snapshot, error) {
	snapshot := Snapshot{Type: state.Type, Value: state.Value}

	count := func(query string) (int64, error) {
		var n int64
		// QueryRow is not part of orsetQuerier; use the service handle's
		// QueryRow for a DB and fall back through the same SQL for a tx.
		row := s.db.QueryRow(query, documentID)
		if tx, ok := q.(interface {
			QueryRow(string, ...any) rowScanner
		}); ok {
			_ = tx
		}
		if err := row.Scan(&n); err != nil {
			return 0, err
		}
		return n, nil
	}

	switch state.Type {
	case TypeCounter, TypeGSet:
		operations, err := count(`SELECT COUNT(*) FROM crdt_ops WHERE document_id = ?`)
		if err != nil {
			return Snapshot{}, err
		}
